INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49050','fiesta','Fiestas de San Roque y Romería de la Virgen de la Tuiza','Romería, Patronal y Paisajística. Se celebra en Agosto y Septiembre. Gran relevancia en el Parque Natural del Lago de Sanabria; destaca por su multitudinaria romería al santuario de la Tuiza con pendones, gaitas sanabresas y calderetas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49052','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeña festividad vecinal en el valle de la Polvorosa adaptada para los veraneantes, centrada en un almuerzo comunitario en el frontón y música grabada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49053','fiesta','Fiestas de Nuestra Señora de la Asunción y la Virgen del Arenal','Patronal, Taurina y Cultural. Se celebra en Agosto. Gran animación en la Tierra del Pan, famosa por sus encierros urbanos tradicionales de reses bravas por las calles, concurso de peñas locales y verbenas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49054','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal y Enológica. Se celebra en Agosto. Festejos potenciados por sus lagares tradicionales de la Tierra del Vino, combinando la procesión con la apertura de bodegas, jotas zamoranas y orquesta en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49055','fiesta','Fiestas de los Santos Justo y Pastor','Patronal. Se celebra en Agosto. Festejos vecinales mínimos condicionados por la baja demografía en Tierra de Campos, reducidos a una santa misa comunitaria, naipes y aperitivo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49056','fiesta','Fiestas de San Cristobal','Patronal. Se celebra en Julio y Agosto. Sencillos festejos veraniegos con bendición tradicional de vehículos en la Tierra del Pan, juegos infantiles, campeonato de mus y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49057','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Enológica. Se celebra en Agosto. Festejos veraniegos en el valle de Vidriales, caracterizados por meriendas comunitarias tradicionales en sus bodegas subterráneas excavadas y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49058','fiesta','Fiestas de Santo Domingo de Guzmán','Patronal y Jacobea. Se celebra en Agosto. Festividad dinamizada por su fuerte vinculación con la Vía de la Plata jacobea, acogiendo a peregrinos en una parrillada popular y pasacalles tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49059','fiesta','Fiestas de Santa Marina','Patronal. Se celebra en Julio y Agosto. Pequeña festividad veraniega de carácter familiar reducida por la despoblación de la Tierra del Vino, centrada en santa misa y una comida popular.','inventario_fiestas_pdf');
