INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49062','fiesta','Fiestas de Santa Justa','Patronal y Arqueológica. Se celebra en Julio y Agosto. Festejos en la Carballeda dinamizados turísticamente por las visitas a su castro celtíbero de "As Muradellas", con caldereta y música folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49063','fiesta','Fiestas de San Martín','Patronal y Taurina. Se celebra en Agosto (Adelantadas). Festejos estivales en la Tierra de Tábara célebres por su suelta de vaquillas en plaza portátil, encierro infantil de carretones y bailes con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49064','fiesta','Romería de los Viriatos (en honor a la Virgen del Castillo)','Romería y Etnográfica. Se celebra en Junio (Primer fin de semana). Fiesta de Interés Turístico Regional de inmenso impacto etnográfico; destaca por sus colosales pendones de sayagueses de hasta siete metros que avanzan flotando movidos por el viento hacia la ermita del Duero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49065','fiesta','Fiestas de San Agustín (Los Encierros de Fermoselle)','Patronal, Taurina y Enológica. Se celebra en Agosto. Gran capital de los Arribes; sus espectaculares y peligrosos encierros urbanos terminan en su histórica e improvisada plaza mayor de madera, acompañados por la apertura de sus cientos de bodegas medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49066','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Junio y Agosto. Festejos de la Sierra de la Culebra tradicionales por sus toques de gaitas y panderos, parrillada popular comunitaria y bailes dirigidos a los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49067','fiesta','Fiesta de la Filandorra y Fiestas de San Blas','Etnográfica y Patronal. Se celebra en Diciembre (Mascaradas) y Agosto. Notable valor folclórico; su ancestral mascarada invernal de "La Filandorra" exhibe personajes mitológicos disfrazados con cencerros y máscaras de corcho tiznando a los vecinos.','inventario_fiestas_pdf');
