INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49071','fiesta','Fiestas de Santa María Magdalena y Feria de la Madera','Patronal, Alistana y Feria Comercial. Se celebra en Julio. Festejos tradicionales de Aliste que combinan los oficios religiosos con exposiciones de artesanía maderera local, gaitas, parrilladas y música orquestal.','inventario_fiestas_pdf');
