INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49076','fiesta','Fiestas de los Santos Justo y Pastor','Patronal y Taurina. Se celebra en Agosto. Festejos tradicionales de la vega del Duero célebres por su suelta de vaquillas en plaza portátil, cenas populares de peñas y orquestas en la plaza mayor.','inventario_fiestas_pdf');
