INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49148','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Celebración de carácter tradicional agraria en la Tierra del Vino con santa misa de acción de gracias, pasacalles al son del tamboril, campeonato de mus y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49149','fiesta','Fiestas del Santo Cristo de la Humildad','Patronal y Taurina. Se celebra en Agosto. Notable relevancia en el Sayago oriental; destaca por sus tradicionales festejos taurinos de vaquillas al pie de su icónica peña del castillo fortificado, comidas de peñas y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49150','fiesta','Fiestas de Nuestra Señora de la Consonación','Patronal. Se celebra en Agosto. Pequeña festividad familiar en la Carballeda con santa misa tradicional, meriendas comunitarias de hermandad, pasacalles de dulzaina y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49152','fiesta','Fiestas de San Eutropio y Feria del Alfarero','Patronal, Etnográfica y de Muestras. Se celebra en Abril y Agosto. Hito alfarero de la provincia; destaca por la promoción artesanal de sus famosas cazuelas y hornos de barro refractario tradicionales sayagueses, combinada en verano con grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49153','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Festejos de retorno veraniego en la comarca de Alba condicionados por el entorno del embalse de Ricobayo, con santa misa solemne, campeonatos de cartas y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49154','fiesta','Fiestas de San Martín','Patronal, Fronteriza y Etnográfica. Se celebra en Noviembre y Agosto (Verano). Enclave de la alta Sanabria gallego-parlante; destaca en verano por su fuerte identidad folclórica con cantos tradicionales, toques de gaitas gallegas y masivas calderetas serranas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49157','fiesta','Fiestas de la Virgen de la Merced','Patronal, Arribes y Paisajística. Se celebra en Septiembre y Agosto. Festejos dinamizados turísticamente por las visitas al monumental Puente de Requejo sobre los cañones del Duero, combinando los oficios religiosos con comidas vecinales y jotas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49158','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal y Taurina. Se celebra en Agosto. Festejos de la Tierra del Vino célebres por su suelta de vaquillas en calles valladas, concursos de disfraces organizados por las peñas locales, cenas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49160','fiesta','Fiestas de San Blas','Patronal. Se celebra en Agosto (Adelantadas). Festejos estivales mínimos adaptados a la baja demografía cerealista de Tierra de Campos, reducidos a una santa misa de acción de gracias, chinchón y un refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49159','fiesta','Fiestas de la Virgen del Carmen y las Bodegas','Patronal y Enológica. Se celebra en Julio y Agosto. Gran animación en Benavente y los Valles, famosa por la masiva apertura de sus espectaculares y tradicionales cuevas y bodegas excavadas en arcilla, con charangas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49162','fiesta','Feria de Ganado de Porto y Fiestas de Nuestra Señora de la Asunción','Ganadera, Etnográfica y Romería. Se celebra en Agosto y Agosto (Feria tradicional). Gran relevancia ganadera de la alta Sanabria montañesa; su histórica e importante feria reúne abundante ganado vacuno de la sierra, exhibiciones ecuestres, folklore de gaitas y migas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49163','fiesta','Fiestas de San Juan Bautista y Adoración del Niño Jesús','Patronal. Se celebra en Junio y Agosto. Celebración tradicional agraria en la comarca de Toro con santa misa de acción de gracias, campeonato de calva y bolos castellanos, seguidos de una cena popular de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49164','fiesta','Fiesta del Tafarrón y Fiestas de San Blas','Etnográfica, Mascarada y Patronal. Se celebra en Diciembre (Mascaradas) y Agosto. Notable valor folclórico; su ancestral mascarada de "El Tafarrón" exhibe al personaje vestido con un traje de juncos y máscara de hojalata corriendo por las calles con cencerros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49165','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeña festividad vecinal reducida debido a la despoblación en la Tierra de Campos zamorana, centrada en una santa misa tradicional, juegos de naipes y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49166','fiesta','Fiestas de Nuestra Señora de las Victorias y Mercado Medieval','Patronal, Histórica, Recreación y Taurina. Se celebra en Septiembre y Agosto *. Declaradas de Interés Turístico Regional; destaca por el desfile tradicional nocturno de los gigantes y cabezudos "Gigantones", el Toro de Fuego y su colosal mercado en la villa medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49170','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto (Adelantadas). Pequeños festejos rurales en Benavente y los Valles adaptados al turismo familiar, con santa misa cantada, campeonato de cartas en las antiguas escuelas y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49169','fiesta','Fiestas de San de San Benito','Patronal. Se celebra en Agosto (Adelantadas). Festejos vecinales mínimos en Tierra de Campos condicionados por la despoblación, limitados a oficios religiosos tradicionales, chinchón y un aperitivo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49172','fiesta','Fiestas de San Salvador y Etnografía de Aliste','Patronal, Alistana y Micológica. Se celebra en Agosto y Octubre. Notable relevancia en Aliste; destaca por sus tradicionales pasacalles de gaita alistana, jotas locales de peñas y sus potentes actividades e itinerarios de micología en otoño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49173','fiesta','Fiestas de San Juan Bautista y Mascarada de la Cencerra','Etnográfica y Patronal. Se celebra en Junio y Enero. Festejos en Aliste fronterizos que guardan gran valor etnográfico por su ancestral mascarada de "La Cencerra" de los quintos, interpretando ritos satíricos con cencerros por las calles rústicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49174','fiesta','Fiestas de la Virgen de Guadalupe','Patronal y Etnográfica. Se celebra en Septiembre y Agosto. Festejos de montaña al pie del puerto del Padornelo, caracterizados por sus sonidos tradicionales de gaita sanabresa, caldereta popular serrana de cazadores y bailes de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49175','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Celebración tradicional agraria en Tierra de Campos con santa misa de acción de gracias, campeonatos de cartas populares en el teleclub y música disco nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03033','fiesta','Fiestas de San Miguel Arcángel','Patronal y Cultural. Se celebra en Mayo y Agosto (Verano). Festejos en la Tierra del Pan dinamizados por su cercanía metropolitana residencial a la capital, con paellada popular comunitaria, hinchables infantiles y disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49179','fiesta','Fiestas de San Juan y de Nuestra Señora de la Asunción','Patronal. Se celebra en Junio y Agosto. Festejos en Sanabria que agrupan a sus distintos núcleos rurales junto al río Tera, en comidas campestres populares tradicionales de hermandad, jotas serranas y dulzaina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49183','fiesta','Fiestas de San Antón','Patronal y Recreativa. Se celebra en Agosto (Adelantadas). Festejos estivales de Sayago junto a los arribes del Tormes, potenciados por competiciones de juegos tradicionales de cartas, cena popular vecinal y baile público.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49189','fiesta','Romería de la Virgen de la Alcobilla','Romería, Etnográfica y Paisajística. Se celebra en Septiembre (8 de septiembre). Gran relevancia en Sanabria; destaca por su multitudinaria romería tradicional celebrada bajo un monumental e histórico bosque de castaños milenarios, con sonidos de gaitas de fole y pendones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49209','fiesta','Fiestas de San Vitero y Feria del del Asno Zamorano-Leonés','Feria de Muestras, Etnográfica y Alistana. Se celebra en Septiembre y Marzo (Feria artesanal). Hito etnográfico de Aliste; su famosa feria promociona la conservación de la mítica e histórica raza autóctona del asno zamorano-leonés mediante exposiciones, concursos, sonidos de gaitas y degustación de ternera de Aliste.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49207','fiesta','Fiestas de Nuestra Señora de la de la Asunción','Patronal. Se celebra en Agosto. Celebración de carácter familiar orientada al turismo de retorno estival con procesión rústica, campeonatos de cartas populares en las antiguas escuelas y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49210','fiesta','El Zangarrón de Sanzoles (Mascarada de Sanzoles) y Fiestas de la Virgen del del Rosario','Etnográfica, Mascarada, Patronal y Taurina. Se celebra en Diciembre (26 de diciembre) y Agosto. Fiesta de Interés Turístico Regional de gran impacto etnográfico; su mítica y ancestral mascarada invernal de "El Zangarrón" despliega al personaje con máscara de cuero negra, peluca y cencerros corriendo tras los mozos de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49214','fiesta','Fiestas de San Lorenzo y de Nuestra Señora de la Asunción','Patronal, Taurina y Alistana. Se celebra en Agosto. Hito y capital comarcal de la Tierra de Tábara; destaca por sus tradicionales encierros y capeas urbanas, desfiles folclóricos acompañados de dulzaineros y peñas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49216','fiesta','Fiestas de Nuestra Señora de los Rayos','Patronal. Se celebra en Septiembre y Agosto (Verano). Festejos tradicionales de Tierra de Campos orientados al reencuentro de familias emigradas, centrados en actos religiosos, campeonatos de cartas en el teleclub y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49219','fiesta','Fiestas de San Agustín (Fiesta de la Fuente del Vino) y la Vendimia de Toro','Patronal, Enológica, Histórica y Taurina. Se celebra en Agosto y Octubre. Hito monumental e internacional. Su Fiesta de la Vendimia y la tradicional "Fuente del Vino" en San Agustín, donde se reparte vino gratis tras espectaculares encierros y capeas en la histórica plaza, están declaradas de Interés Turístico Regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49220','fiesta','Fiestas de Santa Elena','Patronal. Se celebra en Agosto. Pequeña festividad vecinal en Benavente y los Valles, adaptada al turismo familiar estival, centrada en oficios religiosos tradicionales, campeonato de mus y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49221','fiesta','Fiestas de San Ildefonso y la Virgen del Templo','Patronal, Etnográfica y Arribes. Se celebra en Octubre y Agosto (Verano). Festejos en plenos Arribes del Duero sayagueses, notables por sus pasacalles tradicionales con gaita de fole, comidas populares en los cortinos y animadas verbenas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49222','fiesta','Fiestas de San Antón','Patronal. Se celebra en Agosto (Adelantadas). Festejos de retorno veraniego en la Tierra del Pan con pasacalles de dulzaineros, tradicionales competiciones de calva y bolos castellanos, y cena popular de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49223','fiesta','Fiestas de la Virgen de la Soledad y Feria Transfronteriza del Caballo','Patronal, Feria Comercial y Fronteriza. Se celebra en Septiembre y Agosto. Gran animación en Aliste junto a la raya con Portugal, combinando procesiones tradicionales marianas con una importante feria equina transfronteriza, sonidos de gaitas y gastronomía lusazamorana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49224','fiesta','Fiestas de San Mamés y del Emigrante','Patronal, Sanabresa y Paisajística. Se celebra en Agosto. Festejos de montaña en el valle del río Trefacio, caracterizados por toques tradicionales de gaita sanabresa, caldereta popular serrana en las orillas del río y verbenas dirigidas a veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49225','fiesta','Fiestas de San Justo y Pastor','Patronal. Se celebra en Agosto. Festejos vecinales mínimos adaptados a la baja demografía invernal de la comarca de Vidriales, reducidos a una santa misa comunitaria, naipes en el teleclub y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49226','fiesta','Fiestas de San Antonio de Padua','Patronal y Taurina. Se celebra en Junio y Agosto. Festejos tradicionales de La Guareña célebres por su suelta de vaquillas en calles valladas mudéjares, campeonato de calva, parrillada popular comunitaria y bailes de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49229','fiesta','Fiestas de el Salvador','Patronal. Se celebra en Agosto. Festejos veraniegos mínimos adaptados a la baja demografía a orillas del río Cea, limitados a oficios religiosos marianos tradicionales y merienda popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49230','fiesta','Fiestas de San Andrés','Patronal y Taurina. Se celebra en Agosto (Adelantadas). Gran animación estival en el sur provincial, famosa por sus encierros urbanos de reses bravas por las calles, concentraciones de peñas locales y verbenas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49231','fiesta','Fiestas de la Virgen de la Agonía','Patronal. Se celebra en Agosto. Festejos tradicionales de la vega del Tera orientados al veraneante familiar, con procesión rústica, campeonato de mus, comidas populares vecinales y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49232','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Pequeña festividad vecinal reducida debido a la despoblación en Tierra de Campos, centrada en una santa misa tradicional, juegos de naipes y refresco comunitario en el centro social.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49233','fiesta','Fiestas de San Lorenzo','Patronal y Alistana. Se celebra en Agosto. Festejos de retorno familiar estival en la comarca de Alba con santa misa cantada, campeonato de calva y bolos alistanos, y cena popular de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49234','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal, Taurina y Enológica. Se celebra en Agosto. Festejos tradicionales en plena comarca de la Tierra del Vino, célebres por sus tradicionales encierros urbanos de toros, apertura masiva de lagares antiguos, jotas y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49235','fiesta','Fiestas de la Virgen de la Cuesta','Patronal, Gastronómica y Taurina. Se celebra en Septiembre y Agosto. Relevancia comarcal en la zona de Toro, famosa por su tradicional procesión mariana, encierros de vaquillas por las calles, promoción de repostería local y verbenas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49236','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Festejos de escala estrictamente local adaptados a la demografía veraniega de Tierra de Campos, con santa misa, chinchón y merienda popular en las escuelas antiguas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49237','fiesta','Fiestas de San Julián','Patronal. Se celebra en Agosto (Adelantadas). Pequeña festividad de carácter vecinal en la comarca de Aliste, con oficios religiosos tradicionales, campeonato de cartas en el teleclub y refresco para residentes y veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49238','fiesta','Fiestas de la Virgen de la Magdalena y del Bendito Cristo','Patronal y Taurina. Se celebra en Julio y Agosto. Gran animación en la comarca de Benavente y los Valles, famosa por sus encierros urbanos tradicionales de vaquillas, desfile de disfraces organizados por peñas y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49239','fiesta','Fiestas de San Roque','Patronal y Taurina. Se celebra en Agosto. Festejos de gran arraigo en La Guareña, célebres por sus encierros tradicionales de toros urbanos, pasacalles al son de la dulzaina, caldereta popular y grandes bailes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49240','fiesta','Fiestas de Nuestra Señora de la Asunción y la Zafra','Patronal, Etnográfica y Paisajística. Se celebra en Agosto. Festejos tradicionales de los Arribes sayagueses dinamizados turísticamente por las visitas al entorno del Duero, con jotas al son de la flauta y el tamboril, meriendas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49241','fiesta','Fiestas de la Virgen del Olmo','Patronal y Romería. Se celebra en Septiembre y Agosto. Romería tradicional en la comarca de La Guareña a la ermita de la Virgen, con subasta de banzos al son de la dulzaina, jotas castellanas y meriendas populares de hermandad.','inventario_fiestas_pdf');
