INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49243','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal *. Se celebra en Agosto *. Sencillos festejos veraniegos en el valle del Eria orientados al reencuentro de familias nativas, con santa misa, campeonatos de calva y merienda popular vecinal.','inventario_fiestas_pdf');
