INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49245','fiesta','Fiestas de San Blas','Patronal y Taurina. Se celebra en Agosto (Adelantadas). Festejos estivales en la Tierra del Vino célebres por su suelta de vaquillas en calles valladas, campeonatos de cartas populares, grandes meriendas de peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49247','fiesta','Fiesta de los Carochos de Villalcampo y San Lorenzo','Etnográfica, Mascarada y Patronal. Se celebra en Agosto y Enero (Mascaradas). Festejos en Aliste que ganan valor por su ancestral mascarada invernal, desplegando personajes zoomorfos disfrazados con máscaras, cencerros y folklore de gaita alistana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49248','fiesta','Fiestas de San Félix','Patronal. Se celebra en Agosto. Festejos veraniegos en Tierra de Campos centrados en la santa misa cantada, campeonatos de cartas populares en el teleclub y orquesta nocturna en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49249','fiesta','Fiestas del Santo Cristo de la Vera Cruz','Patronal e Histórica. Se celebra en Agosto. Festejos bajo la colosal estampa de su castillo medieval porticado de la comarca de Toro, albergando parrilladas populares, conciertos de dulzaineros y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49250','fiesta','Fiestas de San Roque (Los Encierros de Villalpando)','Patronal, Taurina e Histórica. Se celebra en Agosto. Hito y capital tradicional de Tierra de Campos; destaca por sus multitudinarios encierros de toros por las calles de su recinto amurallado, monumentales capeas, peñas musicales y verbenas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49251','fiesta','Fiestas de San Esteban','Patronal. Se celebra en Agosto (Adelantadas). Celebración en la Tierra del Pan orientada al turismo de retorno familiar, con procesión tradicional con subasta de banzos, campeonato de mus y parrillada vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49256','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio y Agosto. Pequeña festividad vecinal en los Valles de Benavente adaptada a la baja demografía, con santa misa, campeonato de mus en las antiguas escuelas y un aperitivo comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49262','fiesta','Fiestas de Nuestra Señora de la Encarnación y San Roque','Patronal, Carballeda y Paisajística. Se celebra en Agosto. Notable relevancia estética e hito de la Sierra de la Culebra; combina sus tradicionales verbenas y desfiles folclóricos de peñas con la dinamización turística del avistamiento del lobo ibérico y turismo rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49267','fiesta','Fiestas de San de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeña festividad vecinal en la comarca de Toro reducida por la despoblación rural a actos religiosos tradicionales, campeonato de mus y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49270','fiesta','Fiestas del del Santo Cristo de la de la Vera Cruz','Patronal y Taurina. Se celebra en Septiembre y Agosto *. Festejos estivales en la comarca de Toro célebres por su suelta de vaquillas en calles valladas, concursos de disfraces entre las peñas y orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49273','fiesta','Fiestas de San de San Blas','Patronal y Alistana. Se celebra en Agosto (Adelantadas). Festejos veraniegos para emigrantes en la Tierra de Aliste, con procesión rústica, campeonatos de bolos alistanos, cena popular vecinal y baile de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49275','fiesta','Ferias y Fiestas de San Pedro y Semana Santa de Zamora','Patronal, Religiosa, Cultural, Taurina y Etnográfica. Se celebra en Junio y Marzo/Abril. Hito supremo y masivo de impacto global. Su Semana Santa está declarada de Interés Turístico Internacional, destacando por su sobrecogedor silencio, la procesión del Juramento de San Claudio y el canto del Miserere; las ferias de San Pedro albergan la mítica Feria del Ajo de la Tierra del Pan, la Feria de Alfarería de Pascuas, masivos conciertos y ferias taurinas en el coso de la capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90064','fiesta','Fiestas de Nuestra Señora de la Virgen de la Oliva','Patronal y Etnográfica. Se celebra en Julio. Festejos de arraigo local en la Sierra Norte basados en la tradicional misa con subasta de banzos, caldereta popular para los vecinos y orquesta en la plaza rústica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90065','fiesta','Fiestas de San Blas y la Virgen de la Candelaria','Patronal y Taurina. Se celebra en Febrero. Primeros festejos taurinos del año en la región; destaca por su feria taurina invernal, encierros tradicionales urbanos por el casco histórico y masiva afluencia comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90066','fiesta','Fiestas de la Virgen de Septiembre y San Roque','Patronal y Romería. Se celebra en Julio y Septiembre. Festejos en el Valle del Lozoya marcados por la romería a la ermita de la Virgen de la Antigua, juegos tradicionales infantiles, comida popular y verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','fiesta','Fiestas y Ferias de San Bartolomé y Semana Santa de Alcalá','Patronal, Histórica, Cultural y Feria Comercial. Se celebra en Agosto y Marzo/Abril. Hito cultural masivo de Interés Turístico Regional; sus ferias de agosto destacan por la comparsa de gigantes y cabezudos, conciertos de primer nivel, gran recinto de peñas y sus famosas jornadas cervantinas de otoño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90067','fiesta','Fiestas de la Virgen de la Paz y Fiestas de San Isidro','Patronal, Cultural y Recreativa. Se celebra en Enero y Mayo. Gran empaque metropolitano; destaca por la solemne procesión de las antorchas en honor a la virgen, el masivo recinto ferial de peñas en San Isidro con conciertos de figuras nacionales y ferias gastronómicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29002','fiesta','Fiestas en honor a Nuestra Señora de los Remedios','Patronal, Cultural y Recreativa. Se celebra en Septiembre. Macrofestividades de la periferia madrileña; congregan a decenas de miles de personas en su recinto ferial con potentes festivales musicales de pop-rock, espectáculos pirotécnicos, castillos humanos y casetas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90068','fiesta','Fiestas de San Pedro Apóstol y de la Virgen del Fresno','Patronal y Taurina. Se celebra en Junio y Agosto. Gran animación estival dinamizada por las playas del río Alberche, caracterizada por sus encierros tradicionales de reses bravas por las calles vallas, concursos de recortes y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90070','fiesta','Fiestas de Santa Quiteria','Patronal, Taurina y Etnográfica. Se celebra en Mayo. Festejos guadarrameños de gran tradición cantera, célebres por sus encierros de novillos, capeas populares de vaquillas, desfiles folclóricos al son de dulzaineros y peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90071','fiesta','Fiestas del Santísimo Cristo de la Salud y Nuestra Señora de la Cruz','Patronal y Romería. Se celebra en Mayo y Septiembre. Festejos en la comarca de Las Vegas, notables por la procesión tradicional de la virgen hasta su encina monumental, campeonatos de chinchón, caldereta popular vecinal y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90072','fiesta','Fiestas de San Pedro Apóstol y la Virgen de la Oliva','Patronal. Se celebra en Junio y Septiembre. Festejos de arraigo familiar en la Alcarria madrileña con santa misa cantada, campeonato de fútbol sala interpeñas, hinchables infantiles y baile público en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29003','fiesta','Fiestas de San Fernando y Fiestas del Motín de Aranjuez','Histórica, Recreación, Patronal y Taurina. Se celebra en Mayo y Septiembre. Las Fiestas del Motín están declaradas de Interés Turístico Nacional; se realiza una colosal y masiva representación teatral nocturna a orillas del río Tajo donde los vecinos asaltan el palacio de Godoy con trajes goyescos de época.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28014','fiesta','Fiestas Patronales en honor a la Virgen de la Soledad','Patronal, Taurina y Enológica. Se celebra en Septiembre. Fiesta de Interés Turístico Regional de gran arraigo; su célebre feria de novilladas destaca por los peligrosos y multitudinarios encierros urbanos de reses bravas que desembocan en su plaza fija del casco histórico, peñas y conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10023','fiesta','Fiestas del Corpus Christi','Patronal, Cultural y Recreativa. Se celebra en Mayo/Junio. Municipio metropolitano de veloz explosión demográfica; atrae masivamente a la juventud con sus potentes macroverbenas en el recinto ferial, paellada masiva, desfiles humorísticos de peñas locales y fuegos artificiales junto al torreón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28016','fiesta','Fiestas de Santa Catalina','Patronal. Se celebra en Noviembre y Agosto (Verano). Pequeños festejos veraniegos para emigrantes adaptados a la baja demografía invernal de la Sierra Norte, centrados en una comida popular vecinal junto al embalse, naipes y música grabada). ¿Puedo continuar con el siguiente bloque de la provincia de Madrid (Municipios de la B a la C.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28017','fiesta','Fiestas del de la Cruz de la de la Vega y del del de la Salud','Patronal e Histórica. Se celebra en Febrero y Agosto. Festejos estivales bajo la silueta de su monumental castillo gótico-mudéjar vinculado a Garcilaso de la Vega, combinando la misa tradicional con parrilladas populares y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28023','fiesta','Fiestas de San de San Sebastián y de la Virgen de la de la Blanca (en Cerceda y Mataelpino)','Patronal, Taurina y Etnográfica. Se celebra en Enero, Agosto y Septiembre. Notable repercusión mediática por el "boloencierro" de Mataelpino, un encierro rústico único donde se corre delante de una bola gigante de resina, complementado con capeas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90073','fiesta','Fiestas de Nuestra Señora del del Buen de la Suceso (La Pastorela de de Braojos)','Etnográfica, Patronal y Navideña. Se celebra en Septiembre y Diciembre (Navidad). Hito etnográfico de la Sierra de Guadarrama por "La Pastorela", una ancestral danza litúrgica barroca ejecutada dentro del templo por pastores vestidos con indumentarias tradicionales al son de zambombas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28026','fiesta','Fiestas de el Santo Cristo del del Consuelo','Patronal, Taurina y Recreativa. Se celebra en Septiembre. Gran animación en la comarca del Guadarrama, famosa por sus encierros urbanos de reses bravas por las calles vallas, concursos de recortes de toros, charangas de peñas y macroverbenas en la plaza mayor herreriana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28028','fiesta','Fiestas del del Santísimo Cristo de los de los Remedios','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Festejos de la Sierra Norte de gran tradición agraria, célebres por sus encierros de novillos, capeas populares de vaquillas, desfiles folclóricos al son de dulzaineros locales y locales de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28033','fiesta','Fiestas del del Santísimo Cristo de la de la Peña y Feria de la de la Aceituna','Patronal, Gastronómica y Taurina. Se celebra en Septiembre y Octubre. Hito gastronómico de la comarca que promociona su queso tradicional y sus aceitunas de Campo Real con Denominación de Calidad, combinado con encierros taurinos urbanos por las calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28034','fiesta','Fiestas de Santa María de la de la Sede (Fiesta del del de la Vaquilla)','Etnográfica y Patronal. Se celebra en Octubre (Mascaradas/Ritos) y Agosto (Verano). Gran valor folclórico en el Valle del Lozoya; conserva el rito tradicional invernal de la vaquilla zangarrón, y en verano celebran comidas vecinales comunitarias, campeonatos de calva y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28036','fiesta','Fiestas del del Santísimo Cristo de la de la Vera Cruz (Fiesta del del de laúd del de Mayo)','Etnográfica y Patronal. Se celebra en Mayo y Septiembre. Festejos en el límite de la Sagra madrileña que conservan el rito tradicional de la "Plantación del Mayo" por los mozos en la plaza de la villa, seguidos de cenas populares y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28037','fiesta','Fiestas de la Virgen del del Fresno (La Feria de el de el del Toro de Cenicientos)','Patronal, Taurina y Gastronómica. Se celebra en Agosto. Hito taurino de gran relevancia nacional considerado la catedral del "toro-toro"; su feria de castas congrega a miles de aficionados para ver corridas de ganaderías duras, encierros y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28038','fiesta','Fiestas de la Virgen de la de la Natividad y Fiesta de los de los Gabarreros','Patronal, Etnográfica, Paisajística y Deportiva. Se celebra en Septiembre y Marzo *. Gran relevancia en la Sierra de Guadarrama; combina sus populosas fiestas estivales y desfiles de peñas con las exhibiciones de corta de troncos tradicionales ligadas al oficio gabarrero medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28040','fiesta','Fiestas de Nuestra Señora del del Consuelo','Patronal, Taurina y Cultural. Se celebra en Septiembre. Hito comarcal del sur de la provincia; destaca por sus tradicionales, históricos y peligrosos encierros urbanos de toros por las calles de trazado rústico, concursos de recortes y verbenas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28041','fiesta','Fiestas de la Virgen del del Rosario','Patronal y Taurina. Se celebra en Octubre y Mayo (Festejos taurinos). Festejos en el nordeste provincial célebres por sus encierros tradicionales urbanos de vaquillas, concentración de peñas locales de jóvenes, parrillada vecinal y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28046','fiesta','Fiestas de el de San Ildefonso y la Virgen de la de la Paz','Patronal y Taurina. Se celebra en Enero y Agosto (Verano/ Novilladas). Festejos estivales de la Sierra de Guadarrama famosos por su feria de novilladas, encierros urbanos tradicionales de reses bravas por las calles y grandes verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28047','fiesta','Fiestas de San de San Antonio de Padua y Santiago Apóstol','Patronal, Cultural y Taurina. Se celebra en Junio y Julio. Capital comercial de la sierra; destaca por sus multitudinarios encierros taurinos por su casco histórico y barrio de la estación, populosos desfiles de peñas, macroconciertos y ferias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28045','fiesta','Fiestas de Nuestra Señora de los de los Remedios (La Fiesta de la de la Vaquilla)','Patronal, Etnográfica, Taurina y Romería. Se celebra en Agosto y Enero (Mascaradas). La Fiesta de la Vaquilla de enero y la de La Maya de mayo están declaradas de Interés Turístico Regional; sus fiestas patronales estivales destacan por sus masivas corridas con figuras mundiales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28044','fiesta','Fiestas de Santiago Apóstol y la Virgen de la de la Soledad','Patronal. Se celebra en Julio y Septiembre. Festejos en la sierra norteoccidental junto al embalse de Valmayor, caracterizados por una gran paellada popular comunitaria, hinchables infantiles de peñas de jóvenes y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28048','fiesta','Fiestas de Santo Domingo de de Silos Mártir','Patronal. Se celebra en Septiembre y Agosto. Festejos de la Alcarria alta madrileña con santa misa solemne, tradicionales torneos de cartas populares en las escuelas antiguas, parrillada popular comunitaria y discomóvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28049','fiesta','Fiestas de San de San Isidro y de Nuestra Señora del del Amor de la Hermoso','Patronal, Cultural y Recreativa. Se celebra en Mayo y Junio. Gran animación en este municipio del cinturón industrial metropolitano; destaca por su desfile humorístico de peñas de jóvenes, variadas actividades infantiles y macroverbenas con orquestas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28053','fiesta','Fiestas de la Virgen del Espino y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Notable afluencia en la Campiña del Henares por sus tradicionales encierros urbanos, capeas de vaquillas en su plaza fija, concurso de recortes de las peñas y macroverbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28054','fiesta','Fiestas de San Bernabé y Romería de la Virgen de la Herrería','Patronal, Romería y Etnográfica. Se celebra en Junio y Septiembre. Su multitudinaria romería en el paraje de La Fresneda es Fiesta de Interés Turístico Regional, destacando el espectacular desfile de carrozas de peñas tiradas por bueyes y bailes de jotas serranas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28055','fiesta','Fiestas del Santo Cristo de la Buena Dicha y de la Virgen de la Soledad','Patronal y Taurina. Se celebra en Octubre. Festejos en el extremo oriental a orillas del Tajo, célebres por sus encierros urbanos de vaquillas, saltos de recortes, caldereta popular y verbenas tradicionales en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28056','fiesta','Fiesta de la Vaquilla (San Sebastián) y Fiestas de la Virgen del de la Oliva','Etnográfica, Mascarada y Patronal. Se celebra en Enero y Agosto. Hito etnográfico madrileño; su ancestral mascarada invernal de "La Vaquilla" destaca por la carrera de los "alcaldes", "alguaciles" y "vaqueros" con cencerros y trajes de honda tradición folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28057','fiesta','Fiestas de San Esteban (Celebradas en la pedanía de Serracines)','Patronal. Se celebra en Agosto. Festejos de carácter local y familiar adaptados a su configuración agraria, centrados en la misa cantada de banzos, campeonatos de cartas en el teleclub y disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28058','fiesta','Fiestas Patronales en honor al de el de el del Santísimo Cristo de la de la Misericordia','Patronal, Cultural, Taurina y Recreativa. Se celebra en Septiembre. Macrofestividades de la periferia sur; congregan a más de cien mil personas con potentes conciertos de rock nacional, espectaculares y multitudinarios encierros de toros urbanos y un recinto ferial de casetas masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28059','fiesta','Fiestas de la Virgen de Ciguiñuela','Patronal, Taurina y Etnográfica. Se celebra en Septiembre. Gran animación en el valle del Jarama con encierros tradicionales nocturnos y diurnos de reses bravas por las calles, la bajada tradicional de la patrona, peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28060','fiesta','Fiestas de la Virgen de Alarilla (Fiesta de la de la Alborada y Embarcación)','Etnográfica, Patronal y Romería. Se celebra en Septiembre. Hito de enorme valor etnográfico regional; destaca la singular y emocionante procesión fluvial nocturna donde la Virgen navega iluminada en barca por el río Tajo acompañada de antorchas y cánticos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28061','fiesta','Fiestas del de el Santo Cristo de las de las Mercedes','Patronal, Taurina y Cultural. Se celebra en Septiembre. Hito taurino de honda tradición serrana; rodeado de dehesas ganaderas, ofrece importantes encierros urbanos de novillos, concursos de recortes, peñas musicales y verbenas populosas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28062','fiesta','Fiestas de Nuestra Señora de los de los Prados','Patronal y Etnográfica. Se celebra en Octubre y Agosto (Verano). Festejos serranos tradicionales al son de la dulzaina y el tamboril, con la subasta tradicional de banzos de la virgen, caldereta popular vecinal en la fragua y orquesta en la plaza rústica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28063','fiesta','Fiestas de la Virgen de la de la Trinidad y San de San Benito','Patronal. Se celebra en Agosto. Festejos estivales sencillos que agrupan a ambos núcleos vecinales del Lozoya, con torneos tradicionales de cartas populares, parrillada popular comunitaria y música de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28064','fiesta','Fiestas de Nuestra Señora del del Rosario','Patronal. Se celebra en Agosto (Adelantadas). Pequeña celebración veraniega de la Sierra Norte de carácter vecinal orientada al turismo familiar, con santa misa litúrgica rústica, campeonato de mus y música grabada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28065','fiesta','Fiestas Patronales en honor a Nuestra Señora de los de los Ángeles','Patronal, Cultural, Romería y Recreativa. Se celebra en Mayo/Junio (Pentecostés). Gran empaque metropolitano del sur; destaca por la multitudinaria e histórica bajada de la Virgen desde el Cerro de los Ángeles, espectaculares conciertos de primer nivel, gran recinto ferial de peñas y desfile de carrozas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28066','fiesta','Fiestas del del de la Asunción y de la Fiesta del del de la Col','Patronal, Gastronómica y Cultural. Se celebra en Agosto y Marzo. Festejos en el suroeste provincial potenciados por su tradicional e importante producción hortícola de coles, combinando las verbenas estivales con degustaciones populares y peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28067','fiesta','Fiestas de la Virgen del del Espino','Patronal, Taurina y Paisajística. Se celebra en Septiembre. Notable animación junto al embalse, célebre por sus encierros tradicionales urbanos de reses bravas por las calles, pasacalles al son de dulzaineros, grandes orquestas y caldereta popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28068','fiesta','Fiestas en honor a San de San Miguel Arcángel y San de San Francisco','Patronal y Taurina. Se celebra en Septiembre y Octubre. Relevancia comarcal por su prestigiosa feria de novilladas, famosa por sus peligrosos y tradicionales encierros urbanos de toros por el casco histórico, concurso de recortes de las peñas y verbenas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28070','fiesta','Fiestas de Nuestra Señora del del Rosario','Patronal. Se celebra en Agosto. Festejos estivales mínimos adaptados a la baja demografía de la Sierra Norte, reducidos a una santa misa comunitaria, campeonato de naipes en el teleclub y un aperitivo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28071','fiesta','Fiestas de San de San Antonio de de Padua y de Nuestra Señora de los de los Dolores','Patronal y Etnográfica. Se celebra en Junio y Agosto. Pequeña festividad en la Sierra del Rincón rústica, centrada en la procesión de banzos por su arquitectura de piedra tradicional negra, caldereta popular y música folk al son de la dulzaina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28072','fiesta','Fiestas de Nuestra Señora de la de la Virgen de la de la Encina (Fiesta de la de la Caldereta)','Patronal, Gastronómica y Taurina. Se celebra en Septiembre. Gran animación en la falda de la sierra; destaca por su histórica y multitudinaria Fiesta de la Caldereta, donde se cocinan decenas de calderos de carne de toro en la plaza porticada, encierros y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28073','fiesta','Fiestas de Santo Domingo de de Guzmán','Patronal y Taurina. Se celebra en Agosto. Festejos en el suroeste industrial de la provincia, célebres por sus tradicionales encierros de vaquillas por las calles vallas, concursos de recortes de toros, charangas de peñas y macroverbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28074','fiesta','Fiestas de Nuestra Señora de de San Nicasio y de Nuestra Señora de la de la Asunción','Patronal, Cultural y Recreativa. Se celebra en Agosto y Octubre. Macrofestividades de la periferia sur; congregan a decenas de miles de personas en el recinto ferial de la Cubierta y San Nicasio con potentes festivales musicales de pop-rock, encierros tradicionales urbanos y casetas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28075','fiesta','Fiestas de Nuestra Señora de las de las Angustias','Patronal e Histórica. Se celebra en Septiembre *. Festejos en la comarca del Henares que aprovechan el marco monumental de sus conventos barrocos ducales, albergando procesiones solemnes, visitas teatrales, comidas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28076','fiesta','Fiestas del del de la Salud y del del de El Salvador','Patronal y Romería. Se celebra en Agosto. Festejos veraniegos en el Valle del Lozoya volcados en el turismo familiar, con procesión de la patrona, campeonatos de cartas populares en las antiguas escuelas y orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28901','fiesta','Fiestas de la Virgen de la de la Soledad (en Lozoyuela) y San de San Blas','Patronal. Se celebra en Septiembre y Febrero. Agrupa las celebraciones tradicionales de sus tres núcleos serranos en una jornada estival con desfile humorístico de peñas locales, paellada popular comunitaria y grandes bailes públicos). ¿Puedo continuar con el siguiente bloque de la Comunidad de Madrid (Municipios de la M a la M)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28078','fiesta','Fiestas de Santa Ana y Fiesta del Esquilado Tradicional','Patronal y Etnográfica. Se celebra en Julio. Festejos de arraigo serrano en el municipio menos poblado de la región, célebres por su demostración folclórica de esquileo a tijera, jotas tradicionales y caldereta vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','fiesta','Fiestas de San Isidro Labrador, Fiesta de la Virgen de la Paloma y Semana Santa de Madrid','Patronal, Cultural, Etnográfica y Religiosa. Se celebra en Mayo, Agosto y Marzo/Abril. Hito masivo global de nivel internacional. Las fiestas de San Isidro llenan la pradera de chulapos, organillos, rosquillas tontas y listas, conciertos en las plazas principales, espectáculos pirotécnicos monumentales en el Retiro y la feria taurina de Las Ventas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28080','fiesta','Fiestas en honor al Santísimo Cristo de la Fiesta y la Virgen de la Soledad','Patronal, Cultural y Taurina. Se celebra en Septiembre. Gran empaque residencial metropolitano de la zona oeste; destaca por sus multitudinarios encierros urbanos de toros, macroconciertos con figuras nacionales, gran desfile de peñas locales y ferias gastronómicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28082','fiesta','Fiestas de la Virgen de Peña Sacra y del Cristo de la Nave','Patronal, Histórica, Romería y Taurina. Se celebra en Junio y Septiembre. Hito turístico e histórico serrano; destaca por su romería tradicional a la ermita de Peña Sacra, encierros urbanos vallas y verbenas populosas bajo la imponente silueta de su castillo bajomedieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28083','fiesta','Fiestas de Nuestra Señora de la Cabeza','Patronal y Taurina. Se celebra en Septiembre. Festejos de gran animación en la Campiña del Henares, célebres por sus encierros urbanos tradicionales de reses bravas por las calles vallas, grandes comidas populares de hermandad de peñas y orquestas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28084','fiesta','Fiestas Patronales de la Virgen de la Angustias','Patronal, Taurina y Cultural. Se celebra en Septiembre. Relevancia comarcal por sus tradicionales, históricos y peligrosos encierros de toros urbanos por las calles vallas, concursos de recortes y verbenas de primer nivel, dinamizadas por las peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28085','fiesta','Fiestas en honor a la Virgen de la Asunción (Fiesta de los Perreros)','Patronal, Etnográfica y Taurina. Se celebra en Agosto y Febrero (Mascaradas). Destaca la ancestral mascarada de "Los Perreros" en invierno con cencerros y ritos paganos; en agosto celebran procesiones tradicionales marianas, novilladas, peñas y caldereta popular serrana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28086','fiesta','Fiestas de Nuestra Señora del Remolino y San Antón','Patronal, Taurina y Enológica. Se celebra en Mayo y Enero. Hito comarcal norteño y puerta de la sierra; destaca por la masiva apertura de sus espectaculares cuevas y bodegas subterráneas de "El Charcón", combinada con tradicionales encierros y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28087','fiesta','Fiestas de la Virgen del Espino','Patronal y Taurina. Se celebra en Septiembre. Festejos estivales de la Sierra de Guadarrama famosos por su feria de novilladas, encierros urbanos tradicionales de reses bravas, concursos de recortes de peñas de jóvenes y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28088','fiesta','Fiestas de la Virgen de Nazaret','Patronal, Etnográfica y Paisajística. Se celebra en Septiembre. Festejos en la Sierra del Rincón dinamizados turísticamente por su famoso hayedo de Montejo, combinando los oficios religiosos rústicos de banzos con jotas tradicionales y caldereta popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28089','fiesta','Fiestas del de el Santo Cristo de la Salud','Patronal y Taurina. Se celebra en Septiembre. Festejos en el sur provincial célebres por su suelta de vaquillas en calles valladas, campeonato de calva, pasacalles al son de charangas, cenas populares de peñas locales y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28090','fiesta','Fiestas de Nuestra Señora del Rosario (Fiestas de Moralzarzal)','Patronal y Taurina. Se celebra en Septiembre. Festejos en la sierra norteoccidental célebres por su prestigiosa feria de novilladas en su coso cubierto fijo, encierros urbanos tradicionales y macroverbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28091','fiesta','Pasión Viviente de Morata de Tajuña y Fiestas de la Virgen de la Antigua','Religiosa, Recreación, Patronal y Gastronómica. Se celebra en Marzo/Abril (Semana Santa) y Septiembre. Su Pasión Viviente es Fiesta de Interés Turístico Regional de gran calado, donde los vecinos escenifican las estaciones con uniformes e indumentarias de época, famosa también por la promoción de las palmeritas de Morata.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28092','fiesta','Fiestas de Nuestra Señora de los Santos y Fiestas del Dos de Mayo de Móstoles','Patronal, Histórica, Recreación y Cultural. Se celebra en Septiembre y Mayo. Las fiestas históricas del Dos de Mayo son Fiesta de Interés Turístico Nacional; se realiza una colosal recreación popular de época napoleónica con trajes goyescos; en septiembre destacan sus encierros tradicionales y conciertos). ¿Puedo continuar con el siguiente bloque de la Comunidad de Madrid (Municipios de la N a la R.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28094','fiesta','Fiestas de San Bartolomé Apóstol y de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Agosto y Octubre. Festejos en la vertiente sur de la Sierra Norte con pasacalles al son de la dulzaina, campeonatos de bolos castellanos, caldereta popular vecinal en las antiguas escuelas y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28095','fiesta','Fiestas de San Miguel Arcángel y de Nuestra Señora de la Estrella','Patronal y Taurina. Se celebra en Mayo y Septiembre. Festejos de la comarca de la Sierra Oeste célebres por su suelta de vaquillas en plaza portátil, encierro infantil de carretones, cenas populares de peñas y orquestas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28096','fiesta','Fiestas Patronales en honor a Nuestra Señora de la Concepción','Patronal, Taurina e Histórica. Se celebra en Septiembre. Fiesta de Interés Turístico Regional de gran arraigo; destaca por sus tradicionales encierros nocturnos por las calles de su casco histórico, su Mercado Siglo de Oro en la plaza porticada medieval y peñas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28099','fiesta','Fiestas en honor al Santísimo Cristo del Amor','Patronal y Taurina. Se celebra en Septiembre. Festejos de gran animación en la Sierra Oeste, famosos por sus encierros camperos a caballo, novilladas en su plaza portátil, concentración de peñas locales y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28093','fiesta','Fiestas de San Antonio de Padua y de Nuestra Señora de la Natividad','Patronal, Taurina y Paisajística. Se celebra en Junio y Septiembre. Notable afluencia en este icónico municipio de la Sierra de Guadarrama, caracterizada por sus encierros tradicionales urbanos, conciertos folk de peñas, caldereta popular serrana y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28097','fiesta','Fiestas de San Mamés y Nuestra Señora de los Remedios','Patronal. Se celebra en Agosto. Pequeña celebración de la Sierra Norte que agrupa a ambos núcleos vecinales, centrada en oficios litúrgicos tradicionales, campeonato de mus, juegos infantiles y música rústica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28100','fiesta','Fiestas del de la Fundación y de las de las Javieradas','Histórica, Recreación y Patronal. Se celebra en Octubre y Mayo. Pone en valor su monumental conjunto histórico herreriano del siglo XVIII, transformando la villa con mercados barrocos, desfiles de época con trajes cortesanos, comidas populares y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28101','fiesta','Fiestas de la Virgen del de la Oliva','Patronal y Cultural. Se celebra en Agosto. Festejos dinamizados turísticamente por su fuerte comunidad de pintores y casonas de piedra tradicionales blancas, con certámenes de pintura rápida, procesión de banzos y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28102','fiesta','Fiestas de la Virgen de la de la Alarilla y el Santo Cristo','Patronal y Romería. Se celebra en Septiembre. Festejos en Las Vegas con romería tradicional a la ermita sobre el cerro, pasacalles al son de la dulzaina, campeonato de calva y grandes verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28104','fiesta','Fiestas en honor a San de San Vicente y el Santo Cristo de la de la Salud','Patronal y Cultural. Se celebra en Mayo y Junio. Municipio metropolitano de veloz crecimiento demográfico; atrae masivamente a la juventud con sus potentes macroverbenas en el recinto ferial, paellada masiva, hinchables infantiles y peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28106','fiesta','Fiestas Patronales en honor a Nuestra Señora de la de la Soledad','Patronal, Cultural y Recreativa. Se celebra en Septiembre. Macrofestividades de la periferia sur madrileña; congregan a decenas de miles de personas con potentes festivales musicales de pop-rock nacional en su recinto de casetas, espectáculos pirotécnicos monumentales y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28107','fiesta','Fiestas de San de San Juan Bautista (en Patones de de Arriba)','Patronal, Histórica y Paisajística. Se celebra en Junio. Gran joya de la arquitectura tradicional de pizarra negra; atrae a numerosos visitantes combinando las procesiones tradicionales de banzos con pasacalles folclóricos de tamboril y meriendas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28108','fiesta','Fiestas de el de San Miguel Arcángel y del del Santo Cristo de la de la Misericordia','Patronal y Taurina. Se celebra en Septiembre. Festejos de la cuenca alta del Jarama célebres por su suelta de vaquillas en plaza portátil, encierro infantil de carretones, desfile humorístico de peñas de jóvenes y grandes orquestas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28109','fiesta','Fiestas de la Virgen de la de la Asunción','Patronal, Recreativa y Paisajística. Se celebra en Agosto. Festejos estivales muy animados junto al embalse de San Juan, potenciados por competiciones de piragüismo popular, parrillada popular comunitaria, peñas locales de jóvenes y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28110','fiesta','Fiestas de Nuestra Señora del del Castillo','Patronal y Taurina. Se celebra en Mayo y Agosto. Festejos de Las Vegas famosos por sus encierros urbanos tradicionales de reses bravas por las calles vallas, concurso de recortes de las peñas, caldereta popular y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28111','fiesta','Fiestas de San de San Benito y del del Santo Cristo del del Socorro','Patronal y Romería. Se celebra en Julio y Septiembre. Destaca la romería tradicional a la ermita en la Alcarria madrileña, acompañada por pasacalles de dulzaineros locales, campeonatos de bolos castellanos y merienda popular vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28112','fiesta','Fiestas de la Virgen del del Rosario','Patronal y Arqueológica. Se celebra en Septiembre y Agosto. Festejos en el Valle del Lozoya dinamizados por las visitas a sus yacimientos prehistóricos de neandertales, combinando los oficios religiosos marianos de banzos con cenas comunitarias vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28113','fiesta','Fiestas del del Santo Cristo del del Calvario y de Nuestra Señora de la de la Asunción','Patronal, Cultural y Recreativa. Se celebra en Mayo y Agosto. Hito en el área metropolitana sur; destaca por su gran desfile humorístico de carrozas de peñas, espectáculos de fuegos artificiales junto a la torre, conciertos pop y macroverbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28114','fiesta','Fiestas de la Virgen de los de los Dolores (en Gandullas) y San de San Roque','Patronal. Se celebra en Agosto. Festejos de la Sierra Norte adaptados a la población estival con santa misa rústica de acción de gracias, campeonato de chinchón y merienda popular vecinal en el frontón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28115','fiesta','Fiestas de Nuestra Señora de la de la Consolación y San de San Sebastián','Patronal, Cultural y Taurina. Se celebra en Septiembre y Enero. El municipio con mayor renta de la región despliega un gran presupuesto para sus fiestas estivales; incluye encierros urbanos tradicionales de toros bravos, masivos conciertos con figuras mundiales y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28116','fiesta','Fiestas de la Virgen de la de la Cabeza','Patronal. Se celebra en Septiembre y Agosto. Celebración tradicional de la Alcarria con santa misa solemne, campeonato de calva y bolos castellanos, seguidos de una cena popular comunitaria y música disco nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28117','fiesta','Fiestas de la Virgen de los de los Dolores','Patronal y Etnográfica. Se celebra en Julio y Agosto. Festejos serranos de la Sierra del Rincón rústicos al son de la dulzaina, con procesión de banzos por su casco, caldereta popular vecinal en la fragua antigua y orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28118','fiesta','Fiestas de la Virgen de los de los Dolores','Patronal. Se celebra en Septiembre y Agosto. Pequeña festividad vecinal en uno de los valles más recónditos de la Sierra del Rincón, reducida por la despoblación a actos religiosos tradicionales, naipes y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28902','fiesta','Fiestas de San de San Isidro (Agrupa los núcleos de de Mangirón, Cinco de la Villas y Serrada)','Patronal. Se celebra en Mayo y Agosto (Verano). Festejos estivales para emigrantes condicionados por el entorno monumental de sus embalses del Lozoya, con torneos de fútbol sala, paellada popular vecinal y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28119','fiesta','Fiestas de San de San Mateo y de la Virgen de la de la Almudena','Patronal y Taurina. Se celebra en Septiembre y Noviembre. Festejos tradicionales de la comarca del Alberche célebres por su suelta de vaquillas en calles valladas, campeonato de calva, cenas populares de peñas locales y orquestas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28120','fiesta','Fiestas de la Virgen de Gracia y San de San Andrés','Patronal, Etnográfica, Romería y Paisajística. Se celebra en Agosto y Noviembre. Hito serrano del Valle del Lozoya dinamizado turísticamente por las visitas al Monasterio de El Paular; destaca por su procesión rústica de banzos, jotas castellanas al son de dulzaineros, caldereta y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28121','fiesta','Fiestas de la Virgen de la de la Alharilla y San de San Diego','Patronal. Se celebra en Noviembre y Agosto. Sencillos festejos veraniegos en las laderas de la Sierra Norte centrados en los actos religiosos tradicionales de la patrona, campeonato de chinchón y refresco vecinal en el teleclub.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28122','fiesta','Fiestas de la Virgen del del Rosario','Patronal. Se celebra en Septiembre y Agosto (Verano). Festejos en la comarca de la Alcarria baja orientados al veraneante familiar, con procesión rústica, campeonatos de cartas populares en las antiguas escuelas y una gran caldereta vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28123','fiesta','Fiestas de San de San Isidro y de la Fiesta del del del Sol','Patronal, Cultural y Recreativa. Se celebra en Mayo y Septiembre. El municipio periférico de mayor explosión demográfica y asociativa; sus populosas festividades llenan el auditorio Miguel Ríos de macroconciertos, masivo recinto de casetas de peñas y ferias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28124','fiesta','Fiestas de la Virgen del del Rosario','Patronal y Etnográfica. Se celebra en Agosto (Adelantadas). Festejos tradicionales de la Sierra Norte vinculados a la memoria rústica de la fragua y el museo de las formas de vida; incluye oficios religiosos tradicionales, calva, jotas castellanas y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28125','fiesta','Fiestas del del Cristo de la de la Agonía (La Procesión y la Quema del de Judas)','Etnográfica, Patronal y Taurina. Se celebra en Marzo/Abril (Semana Santa) y Agosto. Hito etnográfico de la Sierra Oeste por su espectacular "Quema del Judas" en el Domingo de Resurrección con rústicos cánticos; en agosto destacan sus encierros urbanos de toros y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28126','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio y Agosto. Pequeña festividad vecinal en Somosierra reducida debido a la despoblación a actos religiosos litúrgicos tradicionales, campeonato de mus en las antiguas escuelas y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28127','fiesta','Fiestas de San de San Miguel Arcángel y de la Virgen del del Retamar','Patronal, Cultural y Taurina. Se celebra en Septiembre y Mayo. Hito residencial metropolitano occidental de gran afluencia; destaca por sus multitudinarios encierros urbanos de toros por el casco histórico, potentes conciertos pop en el centro multiusos y casetas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28128','fiesta','Fiestas de Nuestra Señora de la de la Asunción y San de San Juan','Patronal y Taurina. Se celebra en Agosto. Festejos serranos rodeados de castañares en el límite con Ávila, caracterizados por encierros de vaquillas por las calles vallas, parrillada popular comunitaria de peñas de jóvenes y orquestas). ¿Puedo continuar con el último bloque de la Comunidad de Madrid para cerrar de forma definitiva los municipios restantes de la S a la Z?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28129','fiesta','Fiestas en honor a la Virgen de Navalazarza','Patronal y Taurina. Se celebra en Septiembre. Notable relevancia en el eje de la A-1 por su prestigiosa feria de novilladas, célebre por sus tradicionales encierros urbanos, populosos desfiles de peñas y macroverbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28130','fiesta','Fiestas de San Fernando y Fiestas de las Peñas','Patronal, Cultural y Recreativa. Se celebra en Mayo. Gran animación en el Corredor del Henares; destaca por su desfile masivo de peñas, recinto de casetas con potentes conciertos pop-rock, encierros taurinos tradicionales y competiciones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28131','fiesta','Fiestas Patronales de San Lorenzo y Romería de la Virgen de Gracia','Patronal, Romería, Histórica y Cultural. Se celebra en Agosto y Septiembre. La romería de la Virgen de Gracia es Fiesta de Interés Turístico Nacional; una multitudinaria comitiva folclórica con trajes serranos y carretas tradicionales sube al amparo del Real Monasterio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49203','fiesta','Fiestas en honor a San Marcos y las Fiestas Patronales de la Natividad','Patronal y Taurina. Se celebra en Abril y Septiembre. Hito comarcal de las Vegas del Jarama, famoso por sus arriesgados encierros tradicionales urbanos de toros bravos por sus calles, concurso de recortes, peñas y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28133','fiesta','Fiestas Patronales en honor a Nuestra Señora la Virgen de la Nueva','Patronal, Taurina y Enológica. Se celebra en Septiembre. Gran empaque comarcal junto al pantano de San Juan; destaca por sus tradicionales encierros de reses bravas por las laderas rústicas, ferias taurinas de renombre, peñas y cata de vinos de la D.O. Vinos de Madrid.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28134','fiesta','Fiestas en honor al Santísimo Cristo de los Remedios (Los Encierros de Sanse)','Patronal y Taurina. Se celebra en Agosto. Fiesta de Interés Turístico Nacional. Conocida como "La Pamplona chica", sus multitudinarios y peligrosos encierros son los segundos más importantes de España; incluye ferias taurinas de primer nivel y macroconciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28135','fiesta','Fiestas de Santiago Apóstol y la Virgen de la Alameda','Patronal. Se celebra en Julio y Agosto. Festejos serranos que agrupan a sus múltiples núcleos de montaña rústicos, caracterizados por campeonatos tradicionales de calva, caldereta popular vecinal y baile de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28136','fiesta','Fiestas del Santo Cristo de la Fe y San Torcuato','Patronal e Histórica. Se celebra en Mayo y Septiembre. Festejos en la Alcarria madrileña bajo el marco de su castillo medieval de Torremocha, con procesión tradicional de banzos, campeonatos de mus en el teleclub y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28140','fiesta','Fiestas de el de San Roque y el Santo Cristo de la Salud','Patronal y Recreativa. Se celebra en Agosto. Festejos muy animados por peñas locales de jóvenes en el sur provincial, caracterizados por grandes paelladas comunitarias en el parque rústico, competiciones de fútbol sala y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28141','fiesta','Fiestas del Santísimo Cristo del Consuelo y de la Virgen del Rosario','Patronal y Cultural. Se celebra en Mayo y Septiembre. Festejos condicionados por su crecimiento residencial en la comarca del Guadarrama, con desfiles humorísticos de peñas locales, parrillada popular comunitaria, hinchables y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28143','fiesta','Fiestas de Nuestra Señora de la Soledad','Patronal y Paisajística. Se celebra en Agosto. Festejos mínimos en el puerto de montaña más alto de la región, adaptados a la baja demografía invernal, centrados en una misa tradicional rústica, naipes y una comida de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28144','fiesta','Fiestas en honor a la Virgen del Rosario','Patronal, Taurina y Paisajística. Se celebra en Agosto. Gran animación estival al pie de la Sierra de Guadarrama, célebre por su tradicional procesión de la patrona bajando del cerro, encierros urbanos vallas, peñas y conciertos multitudinarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28145','fiesta','Fiestas de la Virgen de la Fuente Santo y Mercado Medieval','Patronal, Histórica y Recreación. Se celebra en Mayo y Septiembre. Pone en valor su monumental patrimonio románico y mudéjar que ha sido escenario de cine; combina procesiones tradicionales de banzos con recreaciones medievales, caldereta y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28146','fiesta','Fiestas de los Santos Niños Justo y Pastor','Patronal y Taurina. Se celebra en Agosto. Festejos de Las Vegas famosos por sus encierros urbanos tradicionales de reses bravas por las escarpadas calles, concurso de recortes de las peñas y grandes verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28147','fiesta','Fiestas de la Virgen del Rosario','Patronal y Taurina. Se celebra en Agosto. Festejos en la confluencia del Jarama y el Tajuña célebres por su suelta de vaquillas en calles valladas mudéjares, campeonato de calva, cenas populares de peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28148','fiesta','Fiestas Populares de Torrejón y Fiestas Patronales de la Virgen del Rosario','Patronal, Cultural y Recreativa. Se celebra en Junio y Octubre. Hito masivo regional; sus fiestas populares de junio llenan el monumental e inmenso recinto ferial de casetas con conciertos gratuitos de figuras mundiales de primer nivel, encierros y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28149','fiesta','Fiestas del de el Santísimo Cristo del Amparo','Patronal y Cultural. Se celebra en Septiembre. Festejos en el eje de la A-42 condicionados por su desarrollo residencial, con desfile de disfraces organizados por peñas locales de jóvenes, paellada comunitaria y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28150','fiesta','Fiestas de San Nicasio y San Esteban','Patronal, Taurina e Histórica. Se celebra en Octubre y Agosto (Verano). Festejos veraniegos bajo la estampa de los restos de su castillo medieval rústico, célebres por sus encierros tradicionales urbanos de vaquillas, caldereta popular y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28151','fiesta','Fiestas en honor a la Virgen de la Soledad','Patronal, Taurina e Histórica. Se celebra en Septiembre. Notable empaque en la villa gótica de origen medieval; destaca por sus encierros tradicionales de toros por el casco histórico, novilladas, danzas folclóricas de dulzaineros, peñas y orquestas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28152','fiesta','Fiestas de la Virgen del Carmen y de San Roque','Patronal, Cultural y Recreativa. Se celebra en Julio y Agosto. Notable concurrencia en la zona metropolitana norte-occidental, caracterizada por masivos concursos gastronómicos interpeñas, conciertos pop, paellada comunitaria y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28153','fiesta','Fiestas de la Virgen de los Dolores y Feria de Artesanía','Patronal y Cultural. Se celebra en Septiembre. Festejos en la Campiña norteña dinamizados turísticamente por su fuerte comunidad de artesanos y el Museo de la Agricultura, con mercados rústicos, jotas tradicionales y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28154','fiesta','Fiestas de la Virgen del Rosario','Patronal y Taurina. Se celebra en Octubre y Agosto (Festejos principales). Festejos en la comarca del Henares famosos por sus tradicionales encierros urbanos de toros por las calles vallas, concursos de recortes de peñas locales de jóvenes y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28903','fiesta','Fiestas de San Juan (Fiestas de Tres Cantos)','Patronal, Cultural y Recreativa. Se celebra en Junio *. El municipio más joven y tecnológico de la región despliega un potente presupuesto para la hoguera masiva de San Juan, conciertos con figuras nacionales, casetas de peñas y ferias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28155','fiesta','Fiestas de la Virgen de la de la Pera Mártir (Fiesta de la Virgen de la Pera)','Patronal. Se celebra en Septiembre. Celebración tradicional de la Alcarria madrileña con santa misa solemne de banzos, campeonato de calva y bolos castellanos, seguidos de una cena popular vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28156','fiesta','Fiestas de la Virgen de la Asunción y la Virgen de las de las Nieves','Patronal. Se celebra en Agosto. Festejos de carácter local y familiar adaptados a su configuración agrícola de la Campiña, centrados en los actos religiosos tradicionales, campeonatos de naipes en el teleclub y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28157','fiesta','Fiestas de la Virgen del Carmen y el Santo Cristo','Patronal y Etnográfica. Se celebra en Julio y Septiembre. Festejos en las escarpaduras de Las Vegas con pasacalles de dulzaina, tradicionales meriendas vecinales comunitarias en las bodegas excavadas en roca y orquesta en la plaza porticada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28158','fiesta','Fiestas de Nuestra Señora del Carmen','Patronal y Etnográfica. Se celebra en Julio. Festejos en la Sierra de La Cabrera vinculados a su histórico gremio de canteros de granito, con exhibiciones de corte, procesión tradicional, caldereta popular serrana y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28159','fiesta','Fiestas de Nuestra Señora de los Prados y Santiago','Patronal. Se celebra en Agosto. Festejos serranos rodeados de pinares junto al puente de Mocha del río Cofio, con procesión tradicional mariana de banzos, campeonatos de mus y parrillada vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28160','fiesta','Fiestas de San Blas y la Candelaria (Feria Taurina de San Blas)','Patronal y Taurina. Se celebra en Febrero. Abre tradicionalmente la temporada taurina europea de primera categoría; su prestigiosa feria invernal en su plaza cubierta fija congrega a miles de aficionados de todo el país, peñas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28161','fiesta','Fiestas del de el Santísimo Cristo de la de la Agonía y Nuestra Señora del del Rosario','Patronal, Cultural y Recreativa. Se celebra en Mayo y Septiembre. Hito demográfico en el sur provincial; atrae masivamente a la juventud con sus potentes macroverbenas en la plaza de la Constitución mudéjar y recinto ferial, desfiles de carrozas de peñas y conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28162','fiesta','Fiestas de San de San Sebastián y la Virgen de la de la Palma (en Alalpardo)','Patronal y Taurina. Se celebra en Agosto (Festejos principales). Festejos de retorno familiar estival en el norte metropolitano, célebres por sus encierros tradicionales urbanos de vaquillas, parrilladas comunitarias de peñas y orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28163','fiesta','Fiestas de San de San Isidro Mártir','Patronal. Se celebra en Mayo y Agosto (Verano). Pequeña festividad vecinal en el límite con Guadalajara adaptada al turismo familiar, con santa misa solemne de banzos, campeonatos de cartas populares en las antiguas escuelas y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28164','fiesta','Fiestas de Nuestra Señora de la de la Asunción y los Encierros del de Jarama','Patronal y Taurina. Se celebra en Septiembre y Agosto. Gran animación en la vega del Jarama, famosa por sus encierros urbanos tradicionales de reses bravas por las calles vallas, concurso de recortes de peñas de jóvenes y verbenas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28165','fiesta','Fiestas de la Virgen del de la Oliva','Patronal y Taurina. Se celebra en Septiembre. Festejos tradicionales de la comarca de Las Vegas célebres por su suelta de vaquillas en calles valladas mudéjares, campeonato de calva, grandes meriendas de peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28166','fiesta','Fiestas de Santo Tomás','Patronal. Se celebra en Agosto (Adelantadas). Festejos estivales mínimos adaptados a la baja demografía agraria de la comarca de Alcalá, reducidos a una santa misa comunitaria, chinchón y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28167','fiesta','Fiestas del del Santo Cristo de la de la Amparo y de la Virgen de la de la Piedad','Patronal y Taurina. Se celebra en Septiembre. Gran animación junto a las lagunas del Jarama; destaca por sus tradicionales encierros urbanos de toros por las calles, populosas charangas de peñas y macroverbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28169','fiesta','Fiestas de San de San Miguel de el de la Atalaya y del del Santo Cristo','Patronal y Cultural. Se celebra en Septiembre y Agosto (Feria tradicional). Puerta de la Sierra Norte; combina sus fiestas patronales con su feria de artesanía y de los oficios rurales tradicionales de banzos, paellada comunitaria de peñas de jóvenes y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28171','fiesta','Fiestas en honor a Santiago Apóstol y los Encierros de la Huerta','Patronal, Taurina y Gastronómica. Se celebra en Septiembre. Hito y capital tradicional hortícola de la Sierra Oeste; destaca por su prestigiosa feria de novilladas, tradicionales encierros de toros urbanos por calles rústicas, peñas y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28170','fiesta','Fiesta del del Melón de de Villaconejos y Fiestas de Santa Ana','Gastronómica, Patronal y Cultural. Se celebra en Julio y Septiembre. Hito gastronómico nacional; su mítica e histórica Fiesta del Melón atrae a multitud de visitantes para celebrar la recogida con ferias de maquinaria, degustaciones masivas, peñas y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28172','fiesta','Fiestas de San de San Miguel y de la Virgen de la de la Poveda','Patronal y Romería. Se celebra en Mayo y Septiembre. Notable concurrencia en la Alcarria debido a su crecimiento residencial; destaca por su multitudinaria romería al santuario de la Poveda, acompañada por pendones tradicionales, cenas de peñas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28173','fiesta','Fiestas de el de San Marcos y del del Santo Cristo de la de la Alborada','Patronal. Se celebra en Abril y Septiembre. Sencillos festejos veraniegos en el valle del Tajo centrados en los actos litúrgicos tradicionales de banzos, campeonato de cartas en el teleclub y merienda popular vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28174','fiesta','Fiestas de el de San Blas y Nuestra Señora de los de los Dolores','Patronal y Taurina. Se celebra en Febrero y Mayo (Festejos principales). Festejos tradicionales de la comarca del Alberche célebres por su suelta de vaquillas en calles valladas mudéjares, campeonato de calva, cenas de peñas locales de jóvenes y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28175','fiesta','Fiestas de San de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto. Celebración de carácter tradicional rural en la comarca del Alberche con santa misa solemne, campeonato de mus en las antiguas escuelas y parrillada vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28176','fiesta','Fiestas de Santiago Apóstol (Fiestas de Villanueva de la Cañada)','Patronal, Cultural y Recreativa. Se celebra en Julio. Municipio metropolitano residencial de gran animación juvenil universitaria; destaca por su masiva concentración de peñas locales, macroverbenas con orquestas potentes en el recinto ferial y ferias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28177','fiesta','Fiestas de San de San Lucas Evagelista','Patronal y Cultural. Se celebra en Octubre y Agosto (Verano). Festejos veraniegos para emigrantes condicionados por su crecimiento residencial metropolitano de la zona oeste, con paellada popular comunitaria, hinchables infantiles de las peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49259','fiesta','Fiestas de Nuestra Señora de la de la Inmaculada *','Patronal *. Se celebra en Diciembre y Agosto (Verano) *. Sencillos festejos veraniegos en el valle del Alberche orientados al reencuentro de familias nativas con campeonato de cartas, juegos infantiles y cena popular vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28179','fiesta','Fiestas de Nuestra Señora de la de la Soledad','Patronal y Taurina. Se celebra en Septiembre. Festejos estivales en el este provincial célebres por su suelta de vaquillas en plaza portátil, pasacalles al son de la dulzaina, caldereta popular y grandes verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28180','fiesta','Fiestas de la Virgen de la de la Victoria y Lepanto','Patronal, Histórica, Recreación y Taurina. Se celebra en Octubre y Septiembre (Festejos principales). Hito histórico comarcal de Las Vegas bajo su monumental torre del homenaje; destaca por su recreación de la batalla de Lepanto de 1571, combinada en septiembre con encierros tradicionales urbanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28181','fiesta','Fiestas en honor al de el de el del Santísimo Cristo de el de el del Milagro y de Nuestra Señora de la de la Soledad','Patronal, Cultural y Recreativa. Se celebra en Septiembre. Gran animación en este municipio residencial metropolitano occidental de gran afluencia; destaca por sus multitudinarios encierros urbanos de toros bravos por el casco histórico, potentes conciertos pop y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28182','fiesta','Fiestas de la Inmaculada Concepción','Patronal. Se celebra en Agosto (Adelantadas). Festejos veraniegos para emigrantes en la Sierra Norte de carácter vecinal, con santa misa litúrgica rústica de banzos, campeonato de mus y parrillada vecinal en el frontón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28183','fiesta','Fiestas de San de San Pedro y de Nuestra Señora de la de la Poveda','Patronal y Etnográfica. Se celebra en Junio y Septiembre. Notable relevancia folclórica al pie de la sierra; combina las procesiones tradicionales rústicas con pasacalles de dulzaineros, comidas de hermandad de peñas locales y verbenas muy animadas en la plaza). Con este bloque cerramos de manera oficial y exhaustiva todos los municipios de la Comunidad de Madrid para el volcado jerárquico del documento. Si deseas pasar a la siguiente región española del índice nacional, indícame si prefieres continuar con Castilla-La Mancha, Cataluña o Andalucía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90820','fiesta','Fiestas en honor a San Miguel Arcángel','Patronal y Etnográfica. Se celebra en Septiembre. Festejos de gran arraigo en la comarca de La Manchuela, famosos por la tradicional carrera de banderas, bailes de jotas al son de dulzaineros locales y verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90337','fiesta','Fiestas de San Juan Bautista y la Virgen del Rosario','Patronal. Se celebra en Junio y Agosto. Festejos de carácter local enfocados en el reencuentro veraniego de familias emigradas, con santa misa cantada, campeonatos de cartas en el centro social y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02001','fiesta','Feria de Albacete (Feria de la Virgen de los Llanos)','Patronal, Macro-Feria Comercial, Taurina y Etnográfica. Se celebra en Septiembre (Del 7 al 17 de septiembre). Declarada Fiesta de Interés Turístico Internacional con un impacto masivo global; destaca su histórico e monumental recinto ferial circular "La Sartén", donde se congregan millones de personas para disfrutar de conciertos, casetas de peñas, una feria taurina de abono de primer nivel y folklore manchego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90338','fiesta','Fiestas en honor a San Ildefonso','Patronal. Se celebra en Enero y Agosto (Verano). Festejos adelantados al verano para los residentes estivales en Campos de Hellín, caracterizados por campeonatos de bochas, meriendas populares colectivas y baile público.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90339','fiesta','Fiestas de Nuestra Señora de la Natividad','Patronal y Enológica. Se celebra en Septiembre. Celebración influenciada por la cultura vitivinícola de La Manchuela, combinando procesiones tradicionales con la cata popular de caldos en cooperativas locales, desfile de carrozas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02002','fiesta','Fiestas de la Virgen del Rosario','Patronal y Taurina. Se celebra en Agosto. Gran animación estival en el somontano de la Sierra de Alcaraz, célebre por sus capeas tradicionales de vaquillas en el coso rústico, cenas populares de peñas y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02003','fiesta','Fiestas en honor a San Lorenzo','Patronal, Taurina y Paisajística. Se celebra en Agosto. Hito turístico e histórico de gran empaque comarcal; sus festejos destacan por los encierros urbanos que bajan por sus escarpadas calles empedradas hacia la singular plaza de toros circular excavada en roca, combinados con verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02004','fiesta','Fiestas de Nuestra Señora de Cortes','Romería, Patronal e Histórica. Se celebra en Septiembre. Fiesta de Interés Turístico Regional de gran fervor; destaca por la multitudinaria e histórica romería que traslada la imagen hasta su santuario en la sierra, flanqueada por desfiles de trajes tradicionales, pendones castellanos y mercados rústicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02005','fiesta','Fiestas Mayores en honor a Nuestra Señora de Belén y Recreación de la Batalla de Almansa','Histórica, Moros y Cristianos, Patronal y Taurina. Se celebra en Mayo y Abril. Sus fiestas de Moros y Cristianos están declaradas de Interés Turístico Internacional, destacando sus espectaculares e históricos desfiles y embajadas nocturnas al pie del imponente castillo medieval; en abril se conmemora la batalla de 1707 con recreaciones de época internacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90821','fiesta','Fiestas de la Santísima Cruz','Patronal y Taurina. Se celebra en Mayo y Agosto. Festejos en el corredor de Almansa célebres por su feria de novilladas, encierros urbanos tradicionales de reses bravas por las calles valladas, tiro al plato y animadas concentraciones de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02006','fiesta','Fiestas Patronales en honor a Santa María de lo Alto','Patronal, Taurina y Paisajística. Se celebra en Septiembre (Del 4 al 8 de septiembre). Notable relevancia en la Sierra del Segura; sus encierros son famosos en toda la provincia por la extrema peligrosidad y belleza plástica al bajar las reses bravas por los vertiginosos acantilados del cañón del río hacia el pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02007','fiesta','Fiestas en honor a San Agustín','Patronal e Histórica. Se celebra en Agosto. Festejos que rememoran su pasado ibérico ligado a la Bicha de Balazote, combinando los oficios religiosos tradicionales con desfiles de carrozas artesanales, paellada comunitaria y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90822','fiesta','Fiestas de San Lorenzo y de la Virgen de la Encarnación','Patronal y Etnográfica. Se celebra en Agosto. Festejos tradicionales de Campo de Montiel centrados en la procesión rústica, competiciones populares de calva y tusa, caldereta popular manchega y baile nocturno con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90341','fiesta','Fiestas en honor a San Roque (La Carrera de las Antorchas)','Etnográfica, Patronal y Taurina. Se celebra en Agosto (Del 13 al 17 de agosto). Hito etnográfico regional de gran vistosidad; destaca la emocionante noche del toro de fuego y la carrera de las antorchas, donde los vecinos corren iluminando al santo por las calles, complementado con capeas y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90342','fiesta','Fiestas de San Bartolomé y la Virgen de Turruchel','Patronal y Romería. Se celebra en Agosto y Septiembre. Notable arraigo serrano al pie de la Sierra de Alcaraz, caracterizado por la romería tradicional a la ermita de Turruchel, pasacalles al son de jotas manchegas y meriendas populares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90343','fiesta','Fiestas del Santo Cristo del de la Vega y los Encierros de Bogarra','Patronal y Taurina. Se celebra en Agosto. Festejos de la Sierra del Segura famosos por sus intensos y arriesgados encierros tradicionales por el casco urbano empinado, concursos de recortes entre peñas locales y verbenas multitudinarias en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90344','fiesta','Fiestas de San Juan Bautista y la Virgen del Rosario','Patronal. Se celebra en Junio y Octubre. Celebración de carácter tradicional rural en la comarca de Monte Ibérico con santa misa solemne, campeonatos de cartas populares en la taberna y orquesta nocturna). ¿Puedo continuar con el siguiente bloque de la provincia de Albacete (Municipios de la C a la L.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90345','fiesta','Fiestas de los Santos Justo y Pastor (La Carrera de los Montones)','Etnográfica, Patronal y Taurina. Se celebra en Agosto (Noche del 23 de agosto). Hito etnográfico regional de gran espectacularidad; destaca la bajada nocturna desde el cerro portando antorchas encendidas para prender fuego a "los montones" de leña, seguida de encierros tradicionales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90346','fiesta','Fiestas en honor a San Isidro Labrador','Patronal y Taurina. Se celebra en Mayo. Festejos de gran animación en La Manchuela con suelta de vaquillas en calles valladas, carrozas tradicionales, campeonatos de petanca y animadas verbenas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90347','fiesta','Fiestas de San José y Nuestra Señora del Rosario','Patronal y Etnográfica. Se celebra en Marzo y Octubre. Celebración serrana tradicional que pone en valor su histórico gremio de telares artesanales, combinando actos religiosos con muestras de artesanía local y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02008','fiesta','Fiestas en honor a San Agustín','Patronal, Taurina y Enológica. Se celebra en Agosto. Capital comercial de La Manchuela albaceteña; destaca por sus tradicionales encierros y capeas en su plaza de toros fija, un masivo desfile de carrozas humorísticas de peñas y ferias del vino local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02009','fiesta','Fiestas de Moros y Cristianos en honor a Nuestra Señora de Gracia','Moros y Cristianos, Histórica y Patronal. Se celebra en Septiembre (Del 6 al 10 de septiembre). Fiesta de Interés Turístico Regional de gran espectacularidad; destaca por sus ancestrales representaciones de "Los Episodios", los vistosos desfiles de comparsas, trabucazos y la danza tradicional del "Volante".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90349','fiesta','Fiestas de la Virgen del de la Abuela (Santa Ana)','Patronal y Etnográfica. Se celebra en Julio. Festejos de La Manchuela famosos por su tradicional "Danza de los Garrotes", pasacalles musicales con dulzaineros locales, gazpachos manchegos comunitarios y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02010','fiesta','Fiestas de la Virgen de las Nieves y Semana Santa de Chinchilla','Patronal, Histórica, Taurina y Religiosa. Se celebra en Agosto y Marzo/Abril. Su Semana Santa y la Soldadesca son de gran valor regional; las fiestas estivales destacan por sus encierros urbanos medievales bajo la silueta de su colosal castillo, peñas musicales y verbenas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90350','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto (Verano). Festejos estivales para emigrantes condicionados por su entorno de lagunas endorreicas, centrados en torneos de cartas, juegos infantiles y música disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90351','fiesta','Fiestas de San Juan Bautista','Patronal y Paisajística. Se celebra en Junio y Agosto. Festejos de montaña en el recóndito entorno de las laderas del río Mundo, caracterizados por la tradicional hoguera de San Juan, comidas populares de cazadores y bailes de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02011','fiesta','Fiestas del Corpus Christi (Alfombras de Serrín) y Fiestas de Septiembre','Etnográfica, Religiosa, Cultural y Taurina. Se celebra en Junio (Corpus) y Septiembre. Declaradas de Interés Turístico Nacional por las espectaculares alfombras de serrín coloreado que cubren las calles la noche del Corpus formando mosaicos monumentales; en septiembre celebran masivos encierros camperos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02013','fiesta','Fiestas del Santo Cristo de la Antigua','Patronal y Taurina. Se celebra en Octubre y Agosto (Verano). Festejos de verano adaptados para los veraneantes en la Sierra del Segura, célebres por su suelta de vaquillas en calles empedradas, encierros infantiles, gazpachada popular y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02032','fiesta','Fiestas de la Virgen de los Remedios','Patronal y Romería. Se celebra en Agosto. Tradicional romería en la comarca de La Mancha Alta que congrega a los pueblos vecinos en su santuario barroco-renacentista, acompañada por pasacalles de dulzaineros, rifas tradicionales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02033','fiesta','Fiestas de San Antonio de Abad (Fiesta de los Sanantones)','Etnográfica, Patronal y Taurina. Se celebra en Octubre y Agosto (Verano). Festejos en la comarca de Campos de Hellín célebres por la pisada de uva tradicional, suelta de vaquillas en coso portátil, charangas de peñas locales y verbenas populosas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02034','fiesta','Fiestas del Santísimo Cristo del Milagro','Patronal, Taurina y Cultural. Se celebra en Agosto. Festejos de gran animación en La Manchuela, dinamizados por la proyección internacional de sus deportistas ilustres; ofrece encierros tradicionales vallas, macroverbenas en la plaza mayor y gazpachos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02036','fiesta','Fiestas de San de San Simeón','Patronal. Se celebra en Febrero y Agosto (Verano). Festejos estivales mínimos adaptados a la baja demografía agraria de La Manchuela, reducidos a una santa misa comunitaria, naipes en el centro social y merienda popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02014','fiesta','Semana Santa de Hellín (La Tamborada de Hellín) y Feria de Septiembre','Etnográfica, Religiosa, Tamborada y Taurina. Se celebra en Marzo/Abril y Septiembre. Su Semana Santa y Tamborada están declaradas de Interés Turístico Internacional, reuniendo a más de veinte mil tamborileros redoblando de forma ininterrumpida; la feria de septiembre destaca por corridas de toros de abono.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02038','fiesta','Fiestas de San de San Pascual Bailón','Patronal. Se celebra en Mayo y Agosto (Verano). Pequeña festividad vecinal en los Llanos de Albacete adaptada para los veraneantes, centrada en una parrillada de hermandad en el frontón y música disco rústica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02039','fiesta','Fiestas de Santa Quiteria','Patronal y Etnográfica. Se celebra en Mayo y Agosto. Festejos tradicionales en el corredor del Almansa que destacan por las meriendas populares en los parajes de pinares, procesión de la santa, campeonatos de calva y baile público con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02040','fiesta','Fiestas de San Pedro de Verona','Patronal. Se celebra en Mayo y Agosto (Verano). Festejos estivales de reencuentro familiar en la comarca de Monte Ibérico, caracterizados por campeonatos de chinchón, una gran cena popular vecinal de hermandad y disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02041','fiesta','Fiestas en honor a la Virgen de Cubas (Alardes de Moros y Cristianos)','Histórica, Recreación y Patronal. Se celebra en Mayo (Del 21 al 23 de mayo). Notable relevancia comarcal en el cañón del Júcar; destaca por sus ancestrales alardes de Moros y Cristianos con textos del siglo XVII recitados frente a sus murallas medievales, jotas y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02016','fiesta','Fiestas Patronales de la Virgen de la de la Asunción (Los Encierros de Letur)','Patronal, Taurina y Paisajística. Se celebra en Agosto (Del 14 al 18 de agosto). Gran hito de la Sierra del Segura; sus encierros tradicionales destacan por la espectacular suelta de reses bravas por las intrincadas calles de su conjunto histórico mudéjar, acompañados por charangas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02043','fiesta','Fiestas de la Virgen de la de la Cruz y Jornadas de Libisosa','Patronal, Arqueológica e Histórica. Se celebra en Mayo y Agosto. Festejos en el Campo de Montiel potenciados por las recreaciones históricas íberoromanas en el yacimiento de Libisosa, combinando procesiones tradicionales con mercados de época y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02044','fiesta','Fiestas Patronales de la Virgen de la de la Muela y Ciclo de Conciertos de Órgano','Cultural, Romería, Taurina y Patronal *. Se celebra en Agosto y Mayo/Junio *. Notable relevancia cultural por su prestigioso ciclo de conciertos de órgano barroco en sus iglesias monumentales; las fiestas estivales incluyen encierros tradicionales escarpados de vaquillas y caldereta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02045','fiesta','Fiestas de San Pedro y San Pablo','Patronal, Taurina y Etnográfica. Se celebra en Junio. Festejos de gran empaque en La Manchuela, célebres por sus tradicionales encierros y capeas urbanas, espectáculos ecuestres, desfiles folclóricos de trajes regionales manchegos y multitudinarias verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02046','fiesta','Fiestas en honor a San Roque','Patronal y Taurina. Se celebra en Agosto. Festejos tradicionales de gran animación comarcal con suelta de vaquillas en calles valladas, campeonatos de pelota a mano, concursos de carrozas artesanales y orquestas por las noches.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02047','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto (Adelantadas). Festejos de retorno estival de carácter familiar en plena Sierra de Alcaraz, centrados en oficios religiosos tradicionales, campeonato de mus en las antiguas escuelas y merienda vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02048','fiesta','Fiestas del Santísimo Cristo de la Guía','Patronal y Taurina. Se celebra en Septiembre. Festejos de gran tradición en el límite norte de La Mancha Alta, célebres por sus encierros urbanos de reses bravas por su llanura rústica, concurso de recortes de peñas y verbenas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02049','fiesta','Fiestas Patronales y Encierros de Molinicos','Patronal, Taurina y Paisajística. Se celebra en Septiembre (Del 3 al 7 de septiembre). Hito taurino serrano en el Parque Natural de los Calares del Mundo; destaca por la altísima peligrosidad de sus encierros de novillos por las angostas y empinadas calles del casco, con peñas y charangas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02050','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto. Festejos vecinales mínimos adaptados a la baja demografía en el eje del Júcar, reducidos a una santa misa comunitaria, campeonato de naipes en el teleclub y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02017','fiesta','Fiestas Patronales en honor a la Virgen de la Consolación','Patronal, Romería y Taurina. Se celebra en Agosto. Notable animación en el Altiplano, destacando su multitudinaria romería al santuario de la Virgen, jotas manchegas, comidas de peñas locales y verbenas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02052','fiesta','Fiestas de Santa Ana','Patronal y Etnográfica. Se celebra en Julio. Festejos que destacan en La Manchuela baja por sus pasacalles folclóricos interpretados por las animadas cuadrillas de música tradicional, gazpachos manchegos populares y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02053','fiesta','Fiestas de la Virgen de la Fuente','Patronal, Etnográfica y Taurina. Se celebra en Septiembre. Gran empaque comarcal en el Campo de Montiel; destaca por sus tradicionales encierros y capeas en calles valladas mudéjares, corridas de toros, el desfile tradicional de trajes manchegos y verbenas populosas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02054','fiesta','Fiestas en honor a San Eleuterio y San Liberato','Patronal. Se celebra en Agosto. Celebración de carácter tradicional rural en La Manchuela con santa misa solemne, campeonato de mus en las antiguas escuelas y parrillada vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02018','fiesta','Fiestas de la Virgen de la Cabeza y Encuentro de Cuadrillas de Nerpio','Etnográfica, Patronal, Gastronómica y Feria Comercial. Se celebra en Agosto y Noviembre (Encuentro de Cuadrillas). Su Encuentro de Cuadrillas es un hito de folclore y música tradicional único en el sureste peninsular; en agosto celebran encierros tradicionales urbanos de vaquillas muy escarpados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02056','fiesta','Fiestas Patronales en honor a San José','Patronal, Taurina y Etnográfica. Se celebra en Marzo. Festejos en Campos de Hellín célebres por sus carreras tradicionales de cintas a caballo, pasacalles al son de bandas de música, capeas en plaza portátil y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02019','fiesta','Fiestas en honor a San Bartolomé','Patronal, Recreativa y Paisajística. Se celebra en Agosto. Gran animación estival dinamizada de forma masiva por el Parque Natural de las Lagunas de Ruidera, caracterizada por sus torneos deportivos náuticos, cenas populares de peñas y macroverbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02060','fiesta','Fiestas del Santo Cristo del Sahúco','Etnográfica, Romería, Patronal y Taurina. Se celebra en Agosto (Noche del 28 de agosto). Fiesta de Interés Turístico Regional de inmenso impacto y fervor; destaca por la impresionante romería donde miles de jóvenes corren a hombros llevando al Cristo a gran velocidad tapados con sábanas blancas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02021','fiesta','Fiestas en honor a San Lorenzo','Patronal y Romería. Se celebra en Agosto. Festejos serranos tradicionales al pie del puerto del Bellotar, caracterizados por marchas de senderismo, romería a la ermita, parrillada popular comunitaria de carne local y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02062','fiesta','Fiestas del Santo Cristo del de la de la Vega (Los Encierros de Povedilla)','Patronal y Taurina. Se celebra en Octubre y Agosto (Verano). Festejos de verano para los retornados en el Campo de Montiel, célebres por sus encierros tradicionales urbanos de novillos de castas bravas, comidas de peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02901','fiesta','Fiestas Patronales de San Juan Bautista','Patronal, Cultural y Taurina. Se celebra en Junio. Gran animación en la comarca de Monte Ibérico; destaca por sus encierros urbanos tradicionales de reses bravas por las calles, concurso de recortes de peñas de jóvenes y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02064','fiesta','Fiestas en honor a San Bartolomé','Patronal. Se celebra en Agosto. Sencillos festejos veraniegos en la llanura de la Manchuela centrados en los actos religiosos tradicionales, campeonato de cartas en el teleclub y merienda popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02022','fiesta','Fiestas de San Juan Bautista (Danza del del Calandario)','Etnográfica, Patronal y Taurina. Se celebra en Junio. Destaca la ancestral Danza del de los Garrotes o Calandario de gran valor folclórico; se complementa en verano con encierros de vaquillas por las calles vallas, comidas comunitarias y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02065','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Pequeña festividad vecinal en el poniente provincial reducida debido a la despoblación a actos religiosos tradicionales de banzos, campeonato de mus y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02023','fiesta','Fiestas en honor a la Virgen de los Dolores (en Riópar Viejo)','Patronal, Histórica y Paisajística. Se celebra en Septiembre y Agosto. Dinamizada turísticamente por las visitas al espectacular nacimiento del río Mundo; combina sus fiestas tradicionales rústicas con pasacalles folclóricos de tamboril y verbenas serranas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02068','fiesta','Fiestas de la Virgen del de la Asunción y San Pedro','Patronal. Se celebra en Junio y Agosto. Festejos estivales en las laderas de la Sierra de Alcaraz orientados al veraneante familiar, con procesión rústica de banzos, campeonato de calva, cena popular y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02015','fiesta','Fiestas Patronales del del de la de El Salvador y Gala Literaria','Patronal, Cultural, Gastronómica y Taurina. Se celebra en Agosto (Primeros de agosto) *. Hito de gran peso comarcal en La Mancha Centro; destaca por sus prestigiosos festivales de peñas locales musicales, corridas de toros de abono de primer nivel y la promoción de los famosos Miguelitos de La Roda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02070','fiesta','Fiestas de la Virgen de la Fuen Santo','Patronal y Romería. Se celebra en Agosto. Romería tradicional en el angosto cañón serrano del río Salobre, con procesión religiosa de banzos al son del tamboril, parrillada popular de carne local de hermandad y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02071','fiesta','Fiestas de San Pedro y San Pablo','Patronal y Taurina. Se celebra en Junio y Agosto. Festejos en el somontano de la sierra célebres por su suelta de vaquillas en calles valladas mudéjares, pasacalles al son de la dulzaina, caldereta popular y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02024','fiesta','Fiestas en honor a Nuestra Señora de la Asunción (Los Encierros de Socovos)','Patronal, Taurina y Paisajística. Se celebra en Agosto (Del 10 al 15 de agosto). Gran animación en la Sierra del Segura; destaca por sus encierros urbanos tradicionales de vaquillas escarpados por las calles empedradas, charangas musicales, cenas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02073','fiesta','Fiestas de San Bartolomé y Carnaval de Tarazona','Etnográfica, Patronal y Taurina. Se celebra en Agosto y Febrero (Carnavales). Su Carnaval está declarado de Interés Turístico Regional por su enorme valor popular sin normas fijas; las fiestas de agosto cuentan con espectaculares encierros taurinos en su colosal plaza porticada barroca del siglo XVII.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02025','fiesta','Semana Santa de Tobarra (La Tamborada de Tobarra y Bendición del de la de El Calvario)','Etnográfica, Religiosa y Tamborada. Se celebra en Marzo/Abril. Su Semana Santa y Tamborada de 104 horas ininterrumpidas están declaradas de Interés Turístico Internacional, culminando en la multitudinaria bendición rústica en el cerro ante decenas de miles de tambores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02075','fiesta','Fiestas de la Virgen del del Rosario','Patronal y Taurina. Se celebra en Agosto (Adelantadas). Gran animación a orillas del río Júcar, famosa por sus encierros tradicionales urbanos de vaquillas vallas, paellada popular comunitaria de peñas de jóvenes y verbenas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02076','fiesta','Auto Sacramental de los Reyes Magos y Fiestas de la Virgen de la de la de la Sede','Etnográfica, Histórica y Patronal. Se celebra en Enero (Día de Reyes) y Agosto. Notable relevancia en la Sierra de Alcaraz por su Auto de los Reyes Magos del siglo XVIII representado por los vecinos en su casco rústico sobre el acantilado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02077','fiesta','Fiestas del Santo Cristo de la Vida y de la de la de El Santuario','Patronal y Romería. Se celebra en Septiembre y Agosto. Festejos bajo el espectacular santuario del Cristo sobre el cañón del Júcar, centrados en los actos litúrgicos marianos tradicionales de banzos y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02078','fiesta','Fiestas de San de San Roque','Patronal. Se celebra en Agosto. Festejos en el valle del Júcar limitando con Cuenca, caracterizados por comidas vecinales comunitarias de hermandad, torneos de fútbol sala y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02026','fiesta','Fiestas en honor a San de San Bartolomé','Patronal, Taurina y Enológica. Se celebra en Agosto. Hito y motor comercial de La Manchuela centro; destaca por sus encierros de novillos por las calles, concurso de peñas musicales, cata de vinos y degustación popular de setas de cultivo local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02080','fiesta','Fiestas del Santo Cristo de la de la Veracruz (La Fiesta de los de los Toros)','Patronal y Taurina. Se celebra en Septiembre (Del 13 al 17 de septiembre). Festejos de gran arraigo en la comarca de Alcaraz, célebres por su suelta tradicional de vaquillas en calles escarpadas valladas mudéjares, cenas populares de peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02027','fiesta','Carnaval de Villarrobledo y Feria de San de San Bernardo','Etnográfica, Cultural, Feria de Muestras y Enológica. Se celebra en Febrero (Carnavales) y Agosto. Su Carnaval está declarado de Interés Turístico Nacional por su masiva e histórica participación y desfiles de comparsas; en agosto celebran importantes ferias comerciales ligadas a su potente industria de tinajas y bodegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02082','fiesta','Fiestas de Nuestra Señora de la de la Asunción','Patronal. Se celebra en Agosto. Pequeñas fiestas veraniegas junto al río Cabriel en el límite con Valencia, con oficios religiosos tradicionales, campeonato de mus en las antiguas escuelas y merienda popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02028','fiesta','Fiestas de San de San Ildefonso','Patronal. Se celebra en Agosto (Adelantadas). Festejos estivales mínimos adaptados a la baja demografía de La Manchuela, reducidos a una santa misa comunitaria, naipes en el teleclub y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02084','fiesta','Fiestas del del de San Blas y Nuestra Señora de los de los Remedios','Patronal. Se celebra en Agosto (Adelantadas). Festejos de montaña en las laderas de la Sierra de Segura al pie de los picos calcáreos, con procesión rústica de banzos, parrillada popular comunitaria y música disco nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02029','fiesta','Fiestas de el Santo Cristo de la de la Columna','Patronal. Se celebra en Agosto. Festejos rurales en el Campo de Montiel orientados al reencuentro de familias nativas con campeonato de cartas, calva y bolos manchegos, y cena popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02030','fiesta','Fiestas Patronales de San Bartolomé (Fiesta de los Llunsa) y Feria de Tradiciones de Yeste','Etnográfica, Patronal, Histórica y Recreación. Se celebra en Agosto y Octubre (Feria de Tradiciones). La Feria de Tradiciones está declarada de Interés Turístico Regional, transformando de forma masiva su castillo con muestras vivas de oficios medievales perdidos, mercadillos, sonidos de cuadrillas y folklore serrano). Con este bloque completamos oficialmente todos los municipios de la provincia de Albacete. ¿Podemos continuar con la siguiente provincia de Castilla-La Mancha (Provincia de Ciudad Real.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90823','fiesta','Fiestas en honor a la Virgen de la Encarnación y San Juan Bautista','Patronal y Etnográfica. Se celebra en Mayo y Junio. Festejos de arraigo comarcal en el Valle de Alcudia, caracterizados por la tradicional ofrenda de roscas, el encendido de hogueras monumentales y animadas verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90323','fiesta','Fiestas de la Virgen de la Estrella y San Roque','Patronal y Taurina. Se celebra en Agosto. Gran animación estival en el límite con Extremadura, famosa por sus encierros tradicionales de reses bravas por las calles valladas, concursos de recortes y verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90324','fiesta','Fiesta de San Antonio de Padua y Las Muñecas de San Juan','Etnográfica y Patronal. Se celebra en Junio. Destaca por la singular tradición de "Las Muñecas", donde los vecinos confeccionan figuras de paja que se cuelgan en las calles y se queman tras los actos litúrgicos marianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90325','fiesta','Fiestas de Santiago Apóstol y la Virgen del Rosario','Patronal e Histórica. Se celebra en Julio y Octubre. Festejos en el Campo de Montiel potenciados por la puesta en valor de su pasado romano, combinando procesiones tradicionales con campeonatos de cartas populares y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13001','fiesta','Carnaval de Alcázar de San Juan (Carnavalcázar) y Feria de los Sabores manchegos','Etnográfica, Gastronómica y Feria de Muestras. Se celebra en Diciembre (Carnaval) y Mayo. Su Carnaval decembrino está declarado de Interés Turístico Regional de gran empaque nacional; la Feria de los Sabores congrega a miles de personas para degustar quesos, vinos de la D.O. La Mancha y folclore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90824','fiesta','Fiestas en honor a la Virgen del Rosario y San Sebastián','Patronal y Paisajística. Se celebra en Mayo y Agosto. Festejos condicionados de forma positiva por su entorno en pleno Parque Nacional de Cabañeros, atrayendo a retornados para calderetas de caza, juegos populares y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90326','fiesta','Fiestas de San Roque y la Virgen de la Asunción','Patronal y Taurina. Se celebra en Agosto. Notable animación por su cercanía a la capital provincial, caracterizada por la suelta de vaquillas en calles valladas, campeonatos de petanca, comidas de peñas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90327','fiesta','Fiestas de la Virgen del Rosario y San Isidro','Patronal. Se celebra en Mayo y Septiembre. Celebración tradicional agraria en el Campo de Montiel con santa misa de acción de gracias, pasacalles de bandas de música locales, campeonato de mus y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90328','fiesta','Fiestas en honor a la Virgen del Valle y San Jorge Mártir','Patronal, Histórica y Romería. Se celebra en Abril y Septiembre. Dinamizada turísticamente por el imponente Sacro Convento Castillo de Calatrava la Nueva, combinando solemnes procesiones del de banzos con pasacalles y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90329','fiesta','Fiestas de San Bartolomé Apóstol','Patronal e Histórica. Se celebra en Agosto. Festejos en el Campo de Montiel bajo la estampa de su castillo medieval, que combinan las procesiones solemnes con visitas culturales a su patrimonio arqueológico e ibérico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90825','fiesta','Fiestas y Ferias de San Pantaleón','Patronal, Minera, Taurina e Histórica. Se celebra en Julio. Hito monumental ligado a su pasado minero patrimonio mundial; destaca por sus corridas de toros en su singular e histórica plaza de toros hexagonal única del siglo XVIII, conciertos y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90330','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Pequeña celebración de carácter familiar adaptada a la demografía estival de la comarca minera, centrada en oficios religiosos tradicionales, campeonato de mus y cena popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90331','fiesta','Almedina Mora y Fiestas de la Virgen de los Remedios','Histórica, Recreación y Patronal. Se celebra en Agosto. Su festival de recreación histórica "Almedina Mora" transforma todo el casco histórico iluminándolo únicamente con miles de velas, zocos artesanales, música e indumentarias de época medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90332','fiesta','Fiestas en honor a la Virgen del Carmen y los Encierros de Almodóvar','Patronal y Taurina. Se celebra en Septiembre (Mediados de septiembre). Fiesta de Interés Turístico Regional de gran impacto; son considerados los encierros más antiguos de España en su modalidad, destacando la extrema peligrosidad de sus carreras vallas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90333','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal. Se celebra en Agosto. Festejos en Despeñaperros que concentran a retornados con pasacalles de bandas de música, torneos de fútbol sala, comidas vecinales comunitarias de hermandad y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90334','fiesta','Fiestas de la Virgen del Rosario','Patronal y Paisajística. Se celebra en Agosto (Adelantadas). Sencillos festejos veraniegos en este enclave rodeado de montes extremeños y toledanos, con santa misa solemne, competiciones infantiles en la plaza y música disco nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90335','fiesta','Fiestas en honor a San Juan Bautista','Patronal. Se celebra en Junio. Celebración tradicional junto al río Cigüela que destaca por sus oficios litúrgicos marianos en su monumental templo románico-mudéjar, parrillada popular y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13003','fiesta','Fiestas en honor a la Virgen de Peñarroya','Patronal, Romería y Cultural. Se celebra en Septiembre y Abril. Notable relevancia comarcal y cervantina; destaca por la multitudinaria romería que traslada a la Virgen desde el Castillo de Peñarroya, acompañada por desfiles folclóricos de peñas y teatro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90336','fiesta','Fiestas Patronales en honor a la Virgen del Socorro','Patronal, Taurina y Cultural. Se celebra en Septiembre. Gran animación en la comarca de Puertollano; ofrece encierros urbanos tradicionales de vaquillas por las calles, pasacalles al son de charangas, grandes verbenas y gazpachada masiva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13021','fiesta','Fiestas de la Virgen de la Candelaria y San Roque','Patronal y Etnográfica. Se celebra en Agosto (Adelantadas). Festejos en el entorno serrano de Cabañeros con procesión de banzos rústica, competiciones de calva y tusa, caldereta popular de carne de caza y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13022','fiesta','Fiestas de San Fernando y la Virgen del de la Consolación','Patronal. Se celebra en Mayo y Agosto. Pequeña festividad vecinal en el Campo de Calatrava adaptada para los veraneantes, centrada en una santa misa comunitaria, campeonatos de naipes en el teleclub y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13023','fiesta','Fiestas Patronales de la Virgen del Monte y del Alabí','Patronal, Romería y Taurina. Se celebra en Septiembre y Abril (Romería). Hito devocional del Campo de Calatrava; la romería de la Virgen del Monte reúne a decenas de miles de personas en sus olivares con subastas tradicionales, corridas de toros y macroverbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13024','fiesta','Fiestas en honor a San Isidro Labrador y San Roque','Patronal y Taurina. Se celebra en Mayo y Agosto. Festejos del Valle de Alcudia célebres por su suelta de vaquillas en plaza portátil, pasacalles musicales tradicionales, caldereta popular y bailes públicos con orquesta). ¿Puedo continuar con el siguiente bloque de la provincia de Ciudad Real (Municipios de la C a la F.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13025','fiesta','Fiestas en honor a San Pantaleón y la Virgen de la Bienvenida','Patronal. Se celebra en Julio. Festejos estivales en el Valle de Alcudia centrados en los actos religiosos tradicionales con subasta de banzos, competiciones de cartas populares en el teleclub y orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13026','fiesta','Fiestas del Santo Cristo de la Santa Vera Cruz','Patronal y Serrana. Se celebra en Septiembre. Festejos en pleno Valle de Alcudia adaptados al retorno familiar de vacaciones, con parrillada popular comunitaria, pasacalles al son de tamboriles locales y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13027','fiesta','Semana Santa de Calzada de Calatrava (Juego de las Caras) y Fiestas del Jubileo','Etnográfica, Religiosa y Patronal. Se celebra en Marzo/Abril y Septiembre. El "Juego de las Caras" en Viernes Santo es una Fiesta de Interés Turístico Regional de inmenso impacto; un ancestral rito profano de apuestas de círculos masivos que rememora el sorteo de la túnica de Cristo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13028','fiesta','Fiestas Patronales en honor a la Virgen de Criptana y San Bartolomé','Patronal, Cultural e Histórica. Se celebra en Abril y Agosto. Hito icónico manchego; sus fiestas lucen con esplendor en su famosa Sierra de los Molinos cervantinos, albergando moliendas tradicionales históricas, conciertos folclóricos, peñas y ferias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13030','fiesta','Fiestas de San Antón','Patronal. Se celebra en Agosto (Adelantadas). Festejos estivales mínimos adaptados a la baja demografía bajo las ruinas de su castillo calatravor, limitados a oficios religiosos tradicionales, chinchón y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13031','fiesta','Fiestas de Nuestra Señora de la Encarnación y las Jornadas de Calatrava la Vieja','Patronal, Histórica y Romería. Se celebra en Abril y Julio. Notable relevancia comarcal potenciada por su festival en el yacimiento arqueológico medieval de Calatrava la Vieja, combinando procesiones tradicionales con mercados árabes y cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13032','fiesta','Fiestas en honor a la Virgen del Salido','Patronal y Romería. Se celebra en Agosto y Septiembre (Romería). Tradicional romería en el Campo de Montiel hasta la ermita, caracterizada por pasacalles de dulzaineros, cantos de jotas manchegas y meriendas populares de peñas en los olivares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13033','fiesta','Las Hogueras de Castellar de Santiago (Fiesta de los de los Mayos y las Hogueras)','Etnográfica y Patronal. Se celebra en Septiembre (Noche del 13 de septiembre) y Mayo. Hito etnográfico regional de gran vistosidad; destaca la impresionante noche donde se encienden cientos de hogueras de encina por todas las calles soltando un denso humo negro en un rito purificador ancestral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13004','fiesta','Fiesta de la Pandorga y Romería de Alarcos','Etnográfica, Patronal, Romería y Cultural. Se celebra en Julio (30 y 31 de julio) y Pentecostés (Mayo/Junio). La Pandorga es Fiesta de Interés Turístico Regional de impacto masivo; destaca por el nombramiento del Pandorgo, la ofrenda folclórica con miles de trajes tradicionales manchegos en la catedral y la masiva zurra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13035','fiesta','Fiestas de Nuestra Señora de la Paz','Patronal y Taurina. Se celebra en Enero y Agosto (Verano). Festejos veraniegos para emigrantes célebres por su suelta tradicional de vaquillas en calles valladas mudéjares, campeonato de calva, cenas populares de peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13036','fiesta','Fiestas de Nuestra Señora de las Mercedes','Patronal y Serrana. Se celebra en Septiembre. Sencillos festejos de montaña en los Estados del Duque orientados al turismo de retorno familiar, con santa misa cantada, campeonato de mus y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13037','fiesta','Fiestas del Santo Cristo de la Veracruz (Las Tacillas de Cózar)','Etnográfica, Romería y Patronal. Se celebra en Septiembre. Hito etnográfico del Campo de Montiel por el ancestral juego tradicional y juego popular de "Las Tacillas", un rito de apuestas monetarias con canicas de barro en círculos excavados en piedra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13005','fiesta','Feria y Fiestas de la Virgen de las Cruces','Patronal, Taurina y Feria Comercial. Se celebra en Septiembre (Del 31 de agosto al 5 de septiembre). Gran empaque comarcal dinamizado por el turismo ecológico de las Tablas de Daimiel; destaca por sus ferias comerciales de maquinaria, corridas de toros de abono de primer nivel y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13040','fiesta','Fiestas en honor a San Agustín (Los Encierros de Fernán Caballero)','Patronal y Taurina. Se celebra en Agosto. Gran animación junto al embalse de Gasset; célebre por sus encierros taurinos tradicionales urbanos de toros sueltos por las calles valladas, concursos de cortes de peñas y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13041','fiesta','Fiesta de las Luminarias de Fontanarejo (San Felipe y Santiago)','Etnográfica y Patronal. Se celebra en Abril (Noche del 30 de abril) y Agosto. Hito folclórico de los Montes de Ciudad Real; destaca la noche de "Las Luminarias", donde el pueblo se inunda con hogueras de romero verde que desprenden un aromático e histórico humo blanco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13042','fiesta','Fiesta de la Virgen de los Baños y Feria del del de la Caza','Patronal, Cinegética y Paisajística. Se celebra en Septiembre y Mayo. Festejos en Sierra Madrona rodeados de bosques y pinturas rupestres, caracterizados por la procesión rústica, degustación masiva de carnes de caza de montería, peñas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13043','fiesta','Fiestas de Santo Tomás de Villanueva','Patronal e Histórica. Se celebra en Septiembre. Festejos en el Campo de Montiel vinculados a la cuna rústica del santo agustino, centrados en los oficios religiosos solemnes, campeonato de chinchón y merienda popular vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13044','fiesta','Fiestas Patronales de Santa Quiteria (La Fiesta de los del del Pito)','Patronal y Etnográfica. Se celebra en Mayo (Del 19 al 24 de mayo). Notable relevancia comarcal famosa por las tradicionales "Coplas de Santa Quiteria" interpretadas por los vecinos al son de pitos de caña artesanales castellanos, comidas populares y orquestas). ¿Puedo continuar con el siguiente bloque de la provincia de Ciudad Real (Municipios de la G a la M.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13045','fiesta','Fiestas en honor a San Pantaleón y la Virgen de Oreto y Zuqueca','Patronal, Romería y Arqueológica. Se celebra en Julio y Marzo (Romería). Notable relevancia en el Campo de Calatrava; la romería destaca por el traslado tradicional de la patrona hacia el santuario y yacimiento ibero-romano de Oreto, con subastas de banzos y jotas manchegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13046','fiesta','Fiestas de Nuestra Señora de los Remedios','Patronal. Se celebra en Agosto. Celebración de retorno estival en el Valle de los Pedroches madrileño-manchego, centrada en los actos religiosos tradicionales, campeonatos de cartas en las antiguas escuelas y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13047','fiesta','Carnaval de Herencia y Fiestas de la Virgen de las Mercedes','Etnográfica, Patronal y Gastronómica. Se celebra en Febrero o Marzo (Carnaval) y Septiembre. Declarado Fiesta de Interés Turístico Nacional por su enorme valor etnográfico, destacando figuras únicas como "el Perlé", gigantes y cabezudos históricos, desfiles de comparsas masivos y degustaciones de queso manchego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13048','fiesta','Fiestas en honor a San Bernardo y San Roque','Patronal. Se celebra en Agosto. Pequeña festividad vecinal en pleno Valle de Alcudia adaptada para los veraneantes, centrada en oficios religiosos tradicionales de banzos, campeonatos de mus y parrillada comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13049','fiesta','Fiestas de la Virgen del Rosario y San Juan Bautista','Patronal, Paisajística y Cinegética. Se celebra en Junio y Agosto. Festejos en los Montes de Toledo potenciados por el turismo ecológico de Cabañeros, caracterizados por pasacalles tradicionales, caldereta popular de montería brava y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13050','fiesta','Fiestas de la Virgen del Sagrario','Patronal. Se celebra en Agosto. Festejos estivales mínimos adaptados a la baja demografía agraria de la comarca, reducidos a una santa misa de acción de gracias, chinchón en las escuelas antiguas y aperitivo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13904','fiesta','Fiestas de la Virgen del Carmen','Patronal y Agrícola. Se celebra en Julio. Celebración tradicional de colonización agraria con santa misa de banzos, concursos de destreza con tractor en los campos, merienda comunitaria de hermandad y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13051','fiesta','Fiestas en honor a la Virgen del Rosario','Patronal. Se celebra en Septiembre y Agosto (Verano). Sencillos festejos veraniegos en la confluencia de los ríos Bullaque y Guadiana, con competiciones deportivas fluviales populares, paellada vecinal de hermandad y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13008','fiesta','Feria y Fiestas de los Santos de Malagón','Patronal, Taurina e Histórica. Se celebra en Septiembre (Del 13 al 18 de septiembre). Relevancia comarcal famosa por sus corridas de toros de abono en su plaza fija, su masiva concentración de peñas locales por su casco histórico teresiano y verbenas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13009','fiesta','Feria y Fiestas de Nuestro Padre Jesús del Perdón y Fercam (Feria del Campo)','Feria de Muestras, Patronal, Taurina y Enológica. Se celebra en Julio (Fercam) y Septiembre. Hito comercial manchego de rango nacional; Fercam atrae a miles de profesionales del sector agroganadero, complementado en septiembre con tradicionales encierros y corridas de toros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13010','fiesta','Fiestas de los Desposorios de la Virgen y San José y la Fiesta del Melón (Ferimel)','Patronal, Romería y Gastronómica. Se celebra en Agosto (Fines de agosto). Notable empaque comarcal que destaca por la procesión tradicional de banzos con subastas multitudinarias y la promoción agrícola de su famoso melón de Membrilla en Ferimel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13055','fiesta','Fiestas del Santo Cristo del Calvario','Patronal y Taurina. Se celebra en Julio. Festejos en el Valle de Alcudia célebres por su suelta tradicional de vaquillas en plaza portátil, pasacalles al son de la dulzaina, caldereta de carne local de hermandad y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13011','fiesta','Carnaval de Miguelturra y Fiestas de la Virgen de la Estrella','Etnográfica, Mascarada, Patronal y Cultural. Se celebra en Febrero o Marzo (Carnavales) y Septiembre. Su Carnaval está declarado de Interés Turístico Nacional; destaca la genuina figura de "la Máscara Callejera" que asalta a los vecinos con el grito de "¿A que no me conoces?", bromas y cencerros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13057','fiesta','Montiel Medieval (Homenaje a Pedro I de Castilla) y Fiestas de San Sebastián','Histórica, Recreación y Patronal. Se celebra en Marzo (Montiel Medieval) y Agosto. Hito de recreación histórica regional de gran vistosidad; escenifica la muerte de Pedro I en 1369 transformando todo el casco con mercados feudales, campamentos militares y desfiles de época.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13012','fiesta','Fiestas de San Roque y la Virgen de la Sierra','Patronal y Etnográfica. Se celebra en Agosto. Gran animación en el Campo de Calatrava, destacando por las tradicionales carreras de cintas a caballo, pasacalles de bandas musicales, gazpachos manchegos populares y grandes verbenas). ¿Puedo continuar con el siguiente bloque de la provincia de Ciudad Real (Municipios de la N a la S.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13059','fiesta','Fiestas en honor a San Bartolomé Apóstol','Patronal y Serrana. Se celebra en Agosto. Festejos estivales en los Montes de Toledo orientados al turismo de retorno familiar, con procesión rústica del santo, campeonatos de cartas populares en el teleclub y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13060','fiesta','Fiestas de la Virgen de la Antigua','Patronal y Paisajística. Se celebra en Mayo y Agosto (Verano). Festejos dinamizados por el turismo rural del Parque Nacional de Cabañeros, caracterizados por calderetas de carne de caza, marchas de senderismo y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13061','fiesta','Fiesta de los Mayos de Pedro Muñoz','Etnográfica, Folk y Patronal. Se celebra en Mayo (Noche del 30 de abril al 1 de mayo). Fiesta de Interés Turístico Nacional; destaca la ancestral noche de la "ronda" donde los mozos cantan los mayos a las "mayas" de la villa, seguida de un monumental festival de folklore e indumentaria manchega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13062','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal. Se celebra en Julio. Celebración de carácter tradicional en la comarca de Calatrava, con oficios religiosos solemnes, campeonato de mus en las antiguas escuelas, parrillada vecinal de hermandad y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13063','fiesta','Fiestas de las Cruces de Piedrabuena y Fiestas Patronales de San Bartolomé','Etnográfica, Patronal y Taurina. Se celebra en Mayo (Cruces) y Agosto. Su festividad de las Cruces es de gran empaque regional, vistiendo las peñas monumentales altares cubiertos de musgo y brezo en cuevas; en agosto celebran encierros tradicionales urbanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13064','fiesta','Fiestas de Santa María Magdalena','Patronal y Cultural. Se celebra en Julio. Festejos muy populosos por su cercanía metropolitana a la capital, que combinan las procesiones tradicionales de banzos con actividades recreativas infantiles, paellada comunitaria y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13065','fiesta','Fiesta del Corpus Christi de Porzuna (Danza del Corpus)','Etnográfica, Religiosa y Patronal. Se celebra en Junio (Corpus). Fiesta de Interés Turístico Regional de inmenso valor folclórico; destaca la ancestral danza donde doce danzantes avanzan bailando de espaldas frente a la custodia sobre alfombras de serrín y tomillo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13066','fiesta','Fiestas de Nuestra Señora del Carmen','Patronal, Taurina y Cultural. Se celebra en Julio. Festejos en el Campo de Calatrava célebres por su suelta de vaquillas en calles valladas, campeonatos de cartas en el casino, cenas populares de peñas y orquestas por las noches.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13067','fiesta','Fiestas de Santa Rosa de Lima','Patronal. Se celebra en Agosto. Pequeña festividad vecinal reducida debido a la baja demografía agraria, centrada en una santa misa comunitaria de acción de gracias, naipes y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13068','fiesta','Fiestas de San Juan Bautista y los Encierros de la Puebla','Patronal y Taurina. Se celebra en Junio y Agosto. Gran animación a orillas del río Guadiana, famosa por sus encierros urbanos tradicionales de reses bravas por las calles valladas, comidas de peñas locales y verbenas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13069','fiesta','Fiestas de la Virgen de la Encarnación','Patronal y Romería. Se celebra en Septiembre y Mayo (Romería). Tradicional romería en el Campo de Montiel hasta su ermita forestal, caracterizada por pasacalles de bandas de música locales, caldereta popular y bailes de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13013','fiesta','Feria de Mayo y Fiestas de la Virgen de Gracia (Día del Voto)','Patronal, Macro-Feria Comercial, Minera y Gastronómica. Se celebra en Mayo y Septiembre. Gran capital industrial de la provincia; su Feria de Mayo congrega a miles de personas en el recinto ferial de casetas con macroconciertos; el "Día del Voto" conmemora la salvación de la peste en 1348 con reparto masivo de estofado de vacuno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13014','fiesta','Fiestas de la Virgen de la Blanca','Patronal, Recreativa y Paisajística. Se celebra en Agosto. Festejos veraniegos dinamizados de forma masiva por el entorno turístico de las Lagunas de Ruidera, caracterizados por torneos deportivos de piragüismo popular, comidas de peñas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13073','fiesta','Fiestas del Santo Cristo de la Veracruz','Patronal. Se celebra en Septiembre y Agosto (Verano). Sencillos festejos veraniegos en la llanura de la comarca de Almadén centrados en el reencuentro de familias nativas con campeonatos de cartas, calva y merienda popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13074','fiesta','Fiestas en honor a Santa Elena (Ferias de San Carlos)','Patronal, Histórica y Cultural. Se celebra en Agosto (Adelantadas). Festejos de gran belleza escénica que aprovechan el marco barroco monumental de su plaza mayor porticada del siglo XVIII, albergando parrilladas populares, conciertos folk y música orquestal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13075','fiesta','Fiestas en honor a San Lorenzo Mártir','Patronal. Se celebra en Agosto. Pequeña festividad vecinal en pleno Valle de Alcudia adaptada para los veraneantes, centrada en oficios religiosos tradicionales de banzos, campeonato de mus y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13076','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos estivales mínimos adaptados a la baja demografía en el Campo de Montiel, reducidos a una santa misa comunitaria de acción de gracias, naipes en el teleclub y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13015','fiesta','Fiestas en honor a la Virgen de las Virtudes y Ferias de Agosto','Patronal, Taurina e Histórica. Se celebra en Agosto y Septiembre. Notable relevancia comarcal famosa por sus corridas de toros de abono en su histórica plaza de toros cuadrada única del siglo XVII, anexa al santuario mariano de las Virtudes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13016','fiesta','Feria y Fiestas de la Virgen de la Loreto y Fiesta del Vino (Manchavino)','Patronal, Enológica y Feria Comercial. Se celebra en Agosto y Septiembre (Manchavino). Hito vitivinícola de gran peso comarcal; su festival Manchavino atrae a miles de visitantes para celebrar la vendimia con concursos de catas de vino de la D.O. La Mancha y folklore popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13007','fiesta','Fiestas de Santiago Apóstol y Semana de la Zarzuela de La Solana','Cultural, Patronal y Taurina. Se celebra en Julio y Octubre (Semana de la Zarzuela). Su Semana de la Zarzuela está declarada Fiesta de Interés Turístico Nacional, atrayendo a compañías líricas de todo el país; las ferias de julio cuentan con tradicionales encierros urbanos de vaquillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13080','fiesta','Fiestas de la Virgen de la Antigua','Patronal y Serrana. Se celebra en Agosto. Festejos de montaña en Sierra Madrona orientados al turismo de retorno familiar, con procesión rústica de banzos, campeonato de mus y parrillada vecinal de hermandad). ¿Puedo continuar con el último bloque de la provincia de Ciudad Real para cerrar sus municipios de la T a la Z?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13081','fiesta','Fiestas en honor a Nuestra Señora de Luciana','Patronal, Romería y Arqueológica. Se celebra en Septiembre. Festejos del Campo de Montiel dinamizados por su patrimonio prehistórico de Castillejo del Bonete, célebres por su romería tradicional, subasta de banzos al son de jotas manchegas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13017','fiesta','Feria y Fiestas de Tomelloso y Romería de la Virgen de las Viñas','Patronal, Enológica, Cultural y Feria Comercial. Se celebra en Agosto (Del 24 al 30 de agosto) y Abril (Romería). Hito económico y enológico de rango nacional; su Feria de agosto destaca por la Fiesta de las Letras, macroconciertos y corridas de toros de abono. Su romería de abril es masiva y de gran empaque folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13083','fiesta','Fiestas del Santísimo Cristo del Consuelo','Patronal, Taurina y Cultural. Se celebra en Septiembre. Notable afluencia en el Campo de Calatrava; destaca por sus festivales de teatro en el Patio de Comedias, tradicionales capeas de vaquillas, desfile de peñas de jóvenes y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13084','fiesta','Fiestas de la Virgen de la Vega y Ciclo Internacional de Órgano','Cultural, Patronal e Histórica. Se celebra en Septiembre. Hito cultural que aprovecha la memoria quechaviana de la villa rústica, famoso por los conciertos en su órgano histórico del siglo XVIII, romería tradicional de banzos y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13085','fiesta','Fiestas de la Virgen de la Cabeza y la Borricá de Torrenueva','Etnográfica, Patronal y Taurina. Se celebra en Septiembre y Febrero (La Borricá). Su rito ancestral de las ánimas de "La Borricá" en carnaval es un hito de gran valor etnográfico provincial con jinetes recorriendo el pueblo; en septiembre celebran encierros tradicionales urbanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13086','fiesta','Fiestas de la Virgen del Valle','Patronal. Se celebra en Agosto. Pequeña festividad vecinal de carácter familiar adaptada a la baja demografía en el valle del río Esteras, con santa misa comunitaria de acción de gracias, naipes y refresco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13018','fiesta','Fiestas del Vino de Valdepeñas (en honor a la Virgen de la Consolación)','Enológica, Patronal, Feria Comercial y Cultural. Se celebra en Septiembre (Primera semana de septiembre). Declaradas Fiesta de Interés Turístico Regional de masivo impacto nacional; celebra la vendimia de la D.O. Valdepeñas inundando las bodegas y calles con catas multitudinarias, peñas, folclore y grandes conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13088','fiesta','Fiestas del Santo Cristo de la Clemencia','Patronal. Se celebra en Agosto. Festejos estivales en el Campo de Calatrava adaptados al retorno de emigrantes con santa misa, campeonato de mus en las antiguas escuelas y merienda popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13089','fiesta','Fiestas de San Agustín y Romería de la Virgen de la Carrasca','Patronal y Romería. Se celebra en Agosto y Septiembre (Romería). La romería de "La Carrasca" en el Campo de Montiel es célebre por su plaza de toros rústica anexa al santuario mariano, donde se lidian reses bravas en un ambiente tradicional de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13090','fiesta','Fiestas de San Miguel Arcángel','Patronal y Taurina. Se celebra en Septiembre y Agosto (Verano). Festejos veraniegos para emigrantes en el Campo de Montiel célebres por su suelta de vaquillas en calles valladas mudéjares, pasacalles al son de la dulzaina, caldereta popular y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13091','fiesta','Fiestas de Mayo y Fiestas Patronales de Jesús Nazareno','Patronal y Romería. Se celebra en Mayo y Septiembre. Notable relevancia comarcal famosa por sus tradicionales "Coplas de Mayo", su procesión flanqueada por las alfombras florales de peñas locales de jóvenes, caldereta y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13092','fiesta','Mencatur (Feria de la Caza y el Turismo) y Fiestas de la Virgen de los Desamparados','Feria de Muestras, Cinegética, Patronal y Romería. Se celebra en Agosto (Mencatur) y Mayo. Mencatur es el gran hito de turismo activo y del sector de la montería brava en el Campo de Montiel, complementado con su romería mariana de gran arraigo y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13019','fiesta','Fiestas del Pimiento (Fiesta del Pimiento de Infantes) y Fiestas de Santo Tomás','Gastronómica, Histórica, Patronal y Recreación. Se celebra en Septiembre y Agosto. Su Fiesta del Pimiento está declarada de Interés Turístico Regional, famosa por elaborar el pisto más grande del mundo en su monumental plaza mayor barroco-renacentista del siglo XVII, atrayendo a miles de turistas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13094','fiesta','Fiestas de San Antón','Patronal. Se celebra en Agosto (Adelantadas). Pequeña festividad vecinal reducida debido a la despoblación del Valle de Alcudia, centrada en una santa misa tradicional de acción de gracias y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13095','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos vecinales mínimos adaptados a la baja demografía en el Campo de Calatrava, reducidos a una santa misa comunitaria, naipes en el centro social y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13096','fiesta','Feria y Fiestas de la Virgen de la Sierra','Patronal, Romería, Taurina y Feria Comercial. Se celebra en Septiembre (Del 7 al 12 de septiembre) y Mayo. Gran empaque comarcal junto a las laderas de los Montes de Toledo; destaca por su multitudinaria romería al santuario de la sierra, corridas de toros de abono de primer nivel, peñas y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13097','fiesta','Fiestas de las Paces de Villarta de San Juan (en honor a Nuestra Señora de la Paz)','Etnográfica, Religiosa y Patronal. Se celebra en Enero (Del 23 al 26 de enero). Fiesta de Interés Turístico Regional de inmenso impacto sonoro y visual; destaca la procesión rústica donde decenas de peñas queman de forma masiva miles de docenas de cohetes lanzados a la vez.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13020','fiesta','Fiestas de Santiago Apóstol y el Santo Cristo del Valle','Patronal e Histórica. Se celebra en Julio. Festejos que aprovechan el marco monumental único de su Palacio Renacentista de Don Álvaro de Bazán, albergando parrilladas populares, conciertos folk de dulzaineros y grandes verbenas.','inventario_fiestas_pdf');
